INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('7', 4, '2003', 'Kreslenie grafov funkcií a kriviek v programe Macromedia Flash 5', 'Plotting some Functions and Curves in Macromedia Flash ', '', 'Article', '1335-4981', '', '12', '20', 'Obzory matematiky, fyziky a informatiky', '', 'The article deals with the Math objects and methods and describes how to plot some curves and functions in Macromedia Flash 5.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('8', 4, '2003', 'Malý tresk v CERN', 'The Small Bang in CERN', '', 'Article', '1335-4981', '', '25', '29', 'Obzory matematiky, fyziky a informatiky', '', 'The paper deals with the latest knowledge about the structure of mass, as well as the great experimental success in CERN where quark-gluon plasma was created for a short time.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('9', 4, '2003', 'Porovnanie auskultačnej a oscilometrickej metódy merania krvného tlaku u detí', 'The Comparison of Cirkulatory and Oscillometrics Methods of Measurement Children’s Blood Pressure', '', 'Article', '1335-4981', '', '30', '38', 'Obzory matematiky, fyziky a informatiky', '', 'In the article authors compare both circulatory and oscillometrics methods of blood pressure measurement of children at the age of 6 to 17 years. Obtained results were statistically evaluated. It can be concluded that for long-term observation of blood pressure of children, the application of oscillometrics method is more suitable.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('10', 4, '2003', 'Využitie základných fyzikálnych konštánt v definíciách jednotiek SI', 'The Utilization of Basic Physical Constants in Definition SI Units', '', 'Article', '1335-4981', '', '39', '48', 'Obzory matematiky, fyziky a informatiky', '', 'The historical development of the effort to define the physical units objectively is described. The beginning of this effort is situated to the end of XVIII. Century. The first coherent system of units based by C.F. Gauss, is mentioned, together with the next development using this method, finished by introduction of SI system. The essence of article is dealing with the tendencies to base the units definitions on the fundamental physical constants or natural invariants, such as Planck constant, elementary charge, speed of light an others. The negative influence of the new definition of amper - applying the Josephson and the quantum Hall effect - on the coherency of SI system is described. The aim to introduce a new definition of mass unit - to abolish the prototype of kilogram and to define it on the base of fundamental constants – is described, together with the connected problems.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('11', 4, '2003', 'Isaac Newton a gravitačný zákon', 'Isaac Newton and the Law of Gravitation', '', 'Article', '1335-4981', '', '49', '59', 'Obzory matematiky, fyziky a informatiky', '', 'Gravity is one of the oldest concepts. Its development was very interesting and instructive. Notion of gravity concept before Newton is described in the first part. In the second one Newton\'s life is discussed. After that genesis of Newton\'s gravity law is interpreted. In conclusion one could find short despict of gravity ideas after Newton.', '');
