INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('14', 5, '2003', 'Využitie fyziky pri štúdiu pasívnych elektrických vlastností biologických tkanív', 'The Utilization of Physics in the Study of Passive Electrical Attributes of the Biological Fibres', '', 'Article', '1335-4981', '', '31', '36', 'Obzory matematiky, fyziky a informatiky', '', 'Practical training on Medical Physics and Biophysics at Medical Faculty in Bratislava is directed on experimental study of medical applications of physical laws, physical principles of  modern medical technique and diagnostic and therapeutic methods. Passive electric properties of biological tissues are studied using simple measuring laboratory set.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('15', 5, '2003', 'Modelové experimenty fluktuácií a Brownovho pohybu', 'The Model Experiments of Fluctuations and Brown’s Movement', '', 'Article', '1335-4981', '', '37', '45', 'Obzory matematiky, fyziky a informatiky', '', 'In dem Artikel sind Modell-Experimente den Fluktuationen und der Brownsbewegung eingeführt, die mit der Hilfe des speziellen  Lehrmittel -Sets  realisierbar  sind. Das Set besteht aus einem Lufttisch auf dem sich bei geringerer Reibung die Ferritzylinder mit übereinstimmenden magnetischen Feldern, die gegenseitig abstoßend wirken (Teilchenmodell), bewegen. Experimenten sind  kvantitativ ausgewertet an Hand der Maxwell – Boltzmanns Statistik.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('16', 5, '2003', 'Werner Heisenberg v Bratislave', 'Werner Heisenberg in Bratislava', '', 'Article', '1335-4981', '', '46', '52', 'Obzory matematiky, fyziky a informatiky', '', 'Paper is devoted to visit of Werner Heisenberg – the founder of quantum mechanics a Nobel Prize winner – in Bratislava. Our report is based partly on documents from Comenius University Archives. Other part of documents originates from Werner Heisenberg Archives in Munich. Prof. Heisenberg´s lectures in Bratislava met profound interest and great success. One can say that it was friendly and useful visit for both Prof. Heisenberg and his Slovak colleagues.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('17', 5, '2003', 'Pokusy s jednoduchými prostriedkami', 'Attempts with Sample Equipment', '', 'Article', '1335-4981', '', '53', '54', 'Obzory matematiky, fyziky a informatiky', '', 'The paper presents the instructions to construct a physical experiment made with simple tools, which you can found on your home. The instructions to the similar experiments are at http://www.ddp.fmph.uniba.sk/~bendikova/aktu.htm', '');
