INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('21', 6, '2003', 'Fyzikální úloha jako model skutečnosti', 'The Physics Problemas the model of reality ', '', 'Article', '1335-4981', '', '36', '45', 'Obzory matematiky, fyziky a informatiky', '', 'The Physics Problem as the model of reality In the article Author describes the changements in the Physics Teaching in last time. He studies the position of Physics Problem in the Teaching. He presents the problem as the model of reality. He shows the creation of model, why the simplifications of reality flew to the solving of problem. He accents that many model´s problems was put into International Physics Olympiad.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('22', 6, '2003', 'FERMATOV PRINCÍP MINIMÁLNEHO ČASU alebo Keď dlhšia cesta je rýchlejšia', 'The Fermat’s Principle of Least Time or when the longiest way is quicker', '', 'Article', '1335-4981', '', '46', '51', 'Obzory matematiky, fyziky a informatiky', '', 'The article deals with the Fermat’s Principle of Least Time. This principle states that light travels between any two points in the shortest possible time.', '');
