INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('25', 7, '2003', 'Stručný prehľad objavov v matematike', 'Compendium of Discoveries in Mathematics', '', 'Article', '1335-4981', '', '24', '30', 'Obzory matematiky, fyziky a informatiky', '', 'We present a historical table of the most important discoveries in mathematics.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('26', 7, '2003', 'Rok 2005: Medzinárodný rok fyziky WYP World Year of Physics', 'Year 2005: The World Year of Physics', '', 'Article', '1335-4981', '', '31', '34', 'Obzory matematiky, fyziky a informatiky', '', 'The World Year of Physics 2005 (WYP 2005) is a worldwide celebration of physics and its importance in our everyday lives. The WYP was endorsed by the council EPS in 2001 and supported by IUPAP in October 2002. Physics not only plays important role in the development of science but also has decisive impact on every society. In the year 2005 we will remember 100th anniversary of Albert Einstein paper “Annus mirabilis” This year provides the opportunity to celebrate Einstein, and his great ideas for the science and life in the 21st century.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('27', 7, '2003', 'Hranica fyzikálneho poznania v súčasnosti', 'Frontiers of Physics at the Present Time', '', 'Article', '1335-4981', '', '36', '42', 'Obzory matematiky, fyziky a informatiky', '', 'This paper summarizes the current description of nature on a microscopicscale reflecting our most up to date knowledge. The main goal is to give a popular description and analysis of the Standard Model, as well as to classify elementary particles by using it. A contemporary picture of the structure of matter, and a zoom from macroscopic-objects to the tiniest constituents of matter - quarks, is presented here. The subsequent parts of the paper show concisely the current status, future prospects for research in the field of elementary particles as well as further efforts focused on developing models that would unify the four fundamental interaction.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('28', 7, '2003', 'Paradoxy špeciálnej teórie relativity', 'Paradoxes of the Special Theory of Relativity', '', 'Article', '1335-4981', '', '43', '52', 'Obzory matematiky, fyziky a informatiky', '', 'Paradoxes of the Special Theory of Relativity. Two interesting, but less known, relativistic paradoxes are explained. Using these explanations we show that the idea of a rigid body is not suitable to the Special Theory of Relativity.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('29', 7, '2003', 'Úlohy riešené kvalifikovaným odhadom', 'Solutions of the Physics Problems with the Qualified Approximation', '', 'Article', '1335-4981', '', '53', '58', 'Obzory matematiky, fyziky a informatiky', '', 'There are some concrete high school´s physics exercices analyzed by authors in the article, we need qualificated assuming when we want to know the solution. This method enables us to show some physics exercises to pupils that they normaly wouldn´t be able to do because of  little entrance information or difficult calculus.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('30', 7, '2003', 'Internet a hypertext v prírodovednom vzdelávaní', 'Internet and Hypertext in the Science Education', '', 'Article', '1335-4981', '', '59', '69', 'Obzory matematiky, fyziky a informatiky', '', 'In article be presented some case and knowledge, which be connected with possibilities the Internet in area presentation and  publication on WWW side. The author efforts to describe some practices near creation side with improving hypertext and for example indicate them ascending fashion. Using hypertext approach reader real decision caption in structured system. For user of Internet is this system approach his natural behaviouring at work  with applications various levels of multimedia.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('31', 7, '2003', 'Dve poznámky ku kmitom pružinového kyvadla vo vyučovaní fyziky na strednej škole', 'Two Notes on the Oscillation of the Spring Pendulum in the Teaching of Physics at Secondary School', '', 'Article', '1335-4981', '', '70', '72', 'Obzory matematiky, fyziky a informatiky', '', 'Additional explanation and specification of oscillatory movement of the spring pendulum in the textbook for a high schools.', '');
