INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('36', 8, '2004', 'Hranica fyzikálneho poznania v súčasnosti', 'Current limit of physical knowledge', '', 'Article', '1335-4981', '', '22', '27', 'Obzory matematiky, fyziky a informatiky', '', 'This paper summarizes the current description of nature on a microscopicscale reflecting our most up to date knowledge. The main goal is to give a popular description and analysis of the Standard Model, as well as to classify elementary particles by using it. A contemporary picture of the structure of matter, and a zoom from macroscopic-objects to the tiniest constituents of matter - quarks, is presented here. The subsequent parts of the paper show concisely the current status, future prospects for research in the field of elementary particles as well as further efforts focused on developing models that would unify the four fundamental interaction.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('37', 8, '2004', 'O Maxwellovom posuvnom prúde v kondenzátore', 'About Maxwell´s displacement current in condenser', '', 'Article', '1335-4981', '', '28', '35', 'Obzory matematiky, fyziky a informatiky', '', 'The displacement current improved by James Clerk Maxwell set to describe the physics of electromagnetic fields in compact form was a very intriguing idea. There are simple demonstrative experiments in textbooks of physics, declaring the existence of displacement current in vacuum. More deep insight shows contradictory in realizing of the displacement current as a current inducing magnetic field.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('38', 8, '2004', 'Albert Einstein - k 125. výročiu narodenia', 'Albert Einstein – the 125th anniversary of the birth', '', 'Article', '1335-4981', '', '36', '55', 'Obzory matematiky, fyziky a informatiky', '', 'The paper deals with life and work of Albert Einstein. Unlike articles published in past more attention is concerned to private lives of great physicist. Some Einstein´s philosophical opinions are discussed shortly. There are two attachments devoted to works of Albert Einstein translated into Czech language and to list of books about Einstein published in Slovak or Czech languages.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('39', 8, '2004', 'K pohybu elektrónu naprieč siločiarami homogénneho elektrického poľa podľa učebnice: Fyzika pre 2. ročník gymnázií –  Elektrické pole, Elektrický prúd', 'Electron motion across the field lines of homogenne electrical field according to textbook: Textbook for 2nd class of high school – Electical field Electrical current', '', 'Article', '1335-4981', '', '56', '58', 'Obzory matematiky, fyziky a informatiky', '', 'How to avoid the phrase: „It can be proved...“ from the solution of the problem 3, exercises 1 – Tasks (Problems) on the movement of a charged particle in an electric field, textbook [1].', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('40', 8, '2004', 'Prechod Venuše cez slnečný disk', 'Venus transit over the solar disk', '', 'Article', '1335-4981', '', '59', '60', 'Obzory matematiky, fyziky a informatiky', '', 'European project related to the observation of the rare astronomical event and its application by the measurement of the distance from the Earth to the Sun (astronomical unit).', '');
