INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('42', 9, '2004', 'Ako žiaci SŠ riešili jeden kombinatorický príklad', 'How the Students of Secondary School Solved the one Combinatorial Task', '', 'Article', '1335-4981', '', '8', '21', 'Obzory matematiky, fyziky a informatiky', '', 'The aim of the paper is to discuss some aspects of the combinatorial thinking of secondary school students. We took a small sample of 16 students and gave them a combinatorial problem. Then we tried to classify the different strategies the students took in their solutions.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('43', 9, '2004', 'O tom ako Juraj názorne vysvetľuje svojmu mladšiemu bratovi Michaelovi funkciu mikrovlnnej rúry', 'How George is Explaining to his Younger Brother Michael the Function of the Microwave Oven by Visual Demonstration', '', 'Article', '1335-4981', '', '34', '36', 'Obzory matematiky, fyziky a informatiky', '', 'Microwave oven is nowadays used almost everywhere. Our school physics does not devote attention to the main principle of microwave oven. This paper suggests some half-way solution. This can be explained at least in simple way as peer-to-peer instruction. This small article should give a useful advice, to many teachers too. Such interpretation of the first level and stage can be understood as a small step to humanization of physics.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('44', 9, '2004', 'Tok fyzikálnej veličiny – slovné spojenie alebo veličina?', 'Flow of the Physical Quantity – Phrase or Quantity?', '', 'Article', '1335-4981', '', '37', '41', 'Obzory matematiky, fyziky a informatiky', '', 'In the paper an inadequate use of the term flux in a physical textbook is commented. It is shown – by numerous examples - that the term flux is mostly used as physical quantity, but not in general context. The term flux should not be mixed up with the term flow. The second meaning of this term is also mentioned - the area integral of a vector function.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('45', 9, '2004', 'Kvantová mechanika, Werner Heisenberg a Slovensko', 'Quantum mechanics, Werner Heisenberg and Slovakia', '', 'Article', '1335-4981', '', '42', '54', 'Obzory matematiky, fyziky a informatiky', '', 'This paper is devoted to development of physics from Planck´s hypothesis to rise of quantum mechanics. Emergence of Heisenberg´s matrix mechanics is discussed too. In this connection the life of W. Heisenberg is mentioned shortly. Author describes how two born-in-Slovakia physicists have affected the genesis and development of quantum mechanics. He analyses contribution of Philipp Lenard and Ján Fischer.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('46', 9, '2004', 'Nedostatočné financovanie základných škôl', 'Insufficient Financing of Primary Schools', '', 'Article', '1335-4981', '', '67', '68', 'Obzory matematiky, fyziky a informatiky', '', 'There are noticed some problems of insufficient finances of basic schools in this article.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('47', 10, '2004', 'Od dotyčnice k Maclaurinovým polynómom', NULL, '', 'Article', '1335-4981', '', '1', '20', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('48', 10, '2004', 'O stredoškolských učebniciach z pravdepodobnosti', 'About Textbooks of Probability for Secondary Schools', '', 'Article', '1335-4981', '', '21', '31', 'Obzory matematiky, fyziky a informatiky', '', 'At the present time we use the schoolbooks of T. Hecht [2] and B. Rieèan [4]
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('49', 10, '2004', 'Formal Knowledge, Operative Knowledge, Elegance of Models in Physics', 'Formal Knowledge, Operative Knowledge, Elegance of Models in Physics', '', 'Article', '1335-4981', '', '32', '41', 'Obzory matematiky, fyziky a informatiky', '', 'In this article we are discussing about formal and operative knowledge and recognition in the teaching of physics. This problem is to concern on different teaching subjects on all type schools too. It is particularly important for teaching subjects, in those demand high degree creating and well development constructive thinking. Obtained knowledge of pupils can have high or ultra low creative potential, what will reflects also in their professional life. Among essential and difficult responsibilities of teachers belong to provide creative teaching, that pupils obtaining the most of operative knowledge.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('50', 10, '2004', 'K meraniu magnetického poľa Zeme podľa upraveného a prepracovaného vydania učebnice: Fyzika pre 3. ročník gymnázií', 'To the Measurement of the Earth’s Magnetic Field According to Adjusted and Elaborated Textbook of Physics for the 3rd Grade of Grammar School', '', 'Article', '1335-4981', '', '42', '43', 'Obzory matematiky, fyziky a informatiky', '', 'About the possibility how to improve measurement accuracy of the horizontal part of Earth Magnetic Field according to the textbook [1]', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('51', 10, '2004', 'Fyzikálna rozcvička', 'Physics Exercises', '', 'Article', '1335-4981', '', '44', '45', 'Obzory matematiky, fyziky a informatiky', '', 'This article deals with the motivation at the beginning of the lesson. Students can do a little activity to warm them up. There are introduced two activities for young learners.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('52', 11, '2004', 'Nekonečne malé a veľké veličiny sú súčasťou matematiky', 'Infinitely small and infinitely large quantities in mathematics', '', 'Article', '1335-4981', '', '1', '14', 'Obzory matematiky, fyziky a informatiky', '', 'The subject of the paper is the historical development of the notion of infinitely
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('53', 11, '2004', 'Periodické funkcie', 'Periodic functions', '', 'Article', '1335-4981', '', '15', '23', 'Obzory matematiky, fyziky a informatiky', '', 'In this paper an elementary approach to periodic functions is presented.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('54', 11, '2004', 'Čo je „Maximum Entropy Principle“?', 'What is Maximum Entropy Principle?', '', 'Article', '1335-4981', '', '24', '30', 'Obzory matematiky, fyziky a informatiky', '', 'This paper provides a basic idea of the “Maximum Entropy Principle” formulated by E. T. Jaynes and specifically relevant in statistical mechanics. However, it also can be widely used outside of this discipline. In this paper its use is discussed on an example of modeling spatial organization of society, particularly spatial interaction modeling.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('55', 11, '2004', 'Fyzikálna úloha ako motivačný faktor vo vyučovaní fyziky', 'Physical task as motivating factor in education of Physics', '', 'Article', '1335-4981', '', '31', '40', 'Obzory matematiky, fyziky a informatiky', '', 'The article deals with the didactic analysis of physical examples taking place in domestic and foreign textbooks. With respect to the results of this analysis the author elaborated several demands on the problems of physics, which should contribute to the increase of quality and effectiveness of the school education of physics.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('56', 11, '2004', 'Anketa o vzťahu medzi obľúbenosťou a záujmom o fyziku', 'Questionnare about relationship between popularity and interesting of physics', '', 'Article', '1335-4981', '', '41', '49', 'Obzory matematiky, fyziky a informatiky', '', 'The article informs about the results of a questionnaire, which concerns the popularity of physics, students’ student the teaching of physics and the physics itself. This questionnaire was filled by 32 students, who attend secondary schools all around Slovakia. These students belong to a special narrow group of participants of the FKS (Physics problem solving contest.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('57', 11, '2004', 'Vodné presýpacie hodiny', 'The Interesting Water Clock / Timer', '', 'Article', '1335-4981', '', '50', '53', 'Obzory matematiky, fyziky a informatiky', '', 'The Interesting Water Clock / Timer – The Water Minutes Counter In the teaching of physics are experiments very important, this is in general well known. The great role play there particularly motivational / incentive experiments. Many interesting experiments can be recommended for pupils as home experiments too. This article is devoted to the interesting time-measurement device, which can be built at home – using common stuff around an usual house. Such product should remember us the concise history of time-measurement and can contribute to better understanding of properties of liquids and gases. The time range may be here adjusted from some minutes to some hours, depending mainly on used volume of bottles and on applied liquid\'s properties. Such \"water timer\" is both edifying and interesting ... and it is surely funny also!', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('58', 11, '2004', 'Prehľad názorov na jav trenia v minulosti', 'Historical overview of opinions to phenomena of the friction', '', 'Article', '1335-4981', '', '54', '60', 'Obzory matematiky, fyziky a informatiky', '', 'This paper deals with history of the friction. The main goal of this contribution is to present the opinions of this phenomenon in the past.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('59', 11, '2004', 'Faradayov zákon elektromagnetickej indukcie ako vedecké divadlo', 'Faraday´s Law of Electromagnetic  induction such scientific theatre', '', 'Article', '1335-4981', '', '61', '65', 'Obzory matematiky, fyziky a informatiky', '', 'The first part of the article deals with a method of scientific theatre by which there is possibility how to acquaint students  with the history of physics in adequate way, how to motivate them, how to evoke interest in them and also how to develop many of their skills. Later, the article mentions particular assets for students  by using this teaching method in the 3rd year of Grammar school in the subject matter about Faradays Law of electromagnetic induction and also mentions the own experiences of the author of the article with such realized class according to attached script.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('60', 5, '2003', 'Jean-Paul Pier (ed.): Development of Mathematics 1900-1950', NULL, '', 'Article', '1335-4981', '', '20', '30', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('61', 12, '2005', 'Ako kalkulátor pomohol objaviť matematický poznatok alebo Iteračné metódy na grafickom kalkulátore', 'How the Calculator Helped to Find a Mathematical Knowledge or Using a Graphing Calculator for Interaction Methods', 'kollar2005a', 'Article', '1335-4981', '', '1', '18', 'Obzory matematiky, fyziky a informatiky', '', 'Graphical calculator is one of the tools of information and communication
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('62', 12, '2005', 'Motivačná príprava školskej kombinatoriky', 'Motivational Preparation for Educational Combinatorics', '', 'Article', '1335-4981', '', '19', '32', 'Obzory matematiky, fyziky a informatiky', '', 'Demonstration of the teacher´s training to thematics complex of school
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('63', 12, '2005', 'Comments on Further Education of Physics Teachers in Hungary and Slovakia', 'Comments on Further Education of Physics Teachers in Hungary and Slovakia', '', 'Article', '1335-4981', '', '33', '41', 'Obzory matematiky, fyziky a informatiky', '', 'Due to the decreased social acceptation of physics, permanent education of physics teachers turns out to be necessary. Another problem is the low interest of young people to study physics and technologies. One of possible ways that could lead out from this drawback is the following one: It is necessary to exert maximal effort to make physics popular among young people. To accomplish this goal, the life long education for teachers on high professional and didactic level must be provided and physics education at secondary schools should be made more motivating and more interesting. This is in accordance with the requirements of the European Committee.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('64', 12, '2005', 'Albert Einstein a Slovensko I. Priateľstvo s Aurelom Stodolom', 'Albert Einstein and Slovakia I. Friendship with Aurel Stodola', '', 'Article', '1335-4981', '', '42', '50', 'Obzory matematiky, fyziky a informatiky', '', 'In first part of paper about Einstein\'s contacts with Slovakia friendly relations between famous physicists and great researcher and inventor Aurel Stodola are discussed. Author is decribing how this rare friendship had emerged and how it developed in period from 1908 to 1933.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('65', 12, '2005', 'Maturitná skúška z fyziky na 6-ročnom gymnáziu v Martine', 'Leaving Exam of Physics at 6-years Secondary Grammar School in Martin', '', 'Article', '1335-4981', '', '51', '61', 'Obzory matematiky, fyziky a informatiky', '', 'A six-year-grammar school in Martin is an outcome of an experiment that was carried out at secondary grammar school in Martin since 1995 year. Every school leaving exam from physics consists of written and oral part. In the article, author describes the process of the preparation of students for school leaving exam, creation and evaluation of its written part. Subject matter of an oral part is the solving of problem assignments, a lot of which enables students to reveal themselves to be experimentators and also to explain phenomenons of our everyday life - a bit surprising and meaningful to talk about. One set for oral part of school leaving exam is the part the article.', '');
