INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('69', 13, '2005', 'Classical statistical mechanical models on a lattice', 'Classical Statistical Mechanical Models on a Lattice', '', 'Article', '1335-4981', '', '28', '37', 'Obzory matematiky, fyziky a informatiky', '', 'We give a brief account of lattice models of equilibrium classical statistical mechanics. As a motivation, we start with the destcription of the well-known Ising model.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('70', 13, '2005', 'Obsah a metódy vyučovania prírodných vied - stav a trendy - I', 'Content and Methods in Teaching Natural Sciences – Situation and Trends – I', '', 'Article', '1335-4981', '', '39', '49', 'Obzory matematiky, fyziky a informatiky', '', 'Recent history and the present state of science education in Slovakia are briefly described. Topics included contain: reform of education in Czechoslovakia in 1975 - 1986, new approaches introduced into a few of our schools (projects FAST and IB) and the present trend of science education based on the development of science literacy of pupils and students. We present also a few recommendations for the future development of science education in Slovakia.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('71', 13, '2005', 'Jednotky elektromagnetických veličín', 'Units of Electromagnetical Quantities', '', 'Article', '1335-4981', '', '50', '54', 'Obzory matematiky, fyziky a informatiky', '', 'A short historical review of creation of the names of electric and magnetic values is presented.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('72', 13, '2005', 'Albert Einstein a Slovensko II.  Bol Einstein v Bratislave, alebo nebol?', 'Albert Einstei and Slovakia II. Was Einstein in Bratislava or He  Was Not? ', '', 'Article', '1335-4981', '', '55', '63', 'Obzory matematiky, fyziky a informatiky', '', 'In second part of paper about contacts of great physicist with Slovakia author is analyzing different types of information about Einstein\'s visit in Bratislava. He is pointing out on contradictions between news published in different journals and in different time. Besides that he is stressing that there are two versions in connection with Einstein\'s motivation for visit in Bratislava - Zach\'s one and Sofer\'s one. Till there is no opportunity to answer question: Did visit Einstein Bratislava or not?', '');
