INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('75', 14, '2005', 'Phase diagrams at low temperatures', 'Phase Diagrams at Low Temperatures', '', 'Article', '1335-4981', '', '30', '35', 'Obzory matematiky, fyziky a informatiky', '', 'We give a brief survey of results concerning the low-temperature phase diagrams and their stability for a large class of statistical mechanical models. The results are applied to two popular examples, the Ising and the Blume-Capel model.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('76', 14, '2005', 'Exploring issues related to transport environment using information technology methods', 'Exploring Issues Related to Transport Environment Using Information Technology Methods', '', 'Article', '1335-4981', '', '36', '47', 'Obzory matematiky, fyziky a informatiky', '', 'The paper presents research into transport environment conducted in Szeged (a city with appr. 170 thousand inhabitants), Hungary, and the results of the models developed on the basis of the research. The mathematical models have been illustrated by applying certain information technology procedures. The models provided offer a presentation of environmental load connected to transport of the surrounding settlements, relations between city structure and transport, as well as propagation of air pollution generated by traffic.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('77', 14, '2005', 'On the methodological background of enviromental physics teaching', 'On the Methodological Background of Environmental Physics Teaching', '', 'Article', '1335-4981', '', '48', '51', 'Obzory matematiky, fyziky a informatiky', '', 'In this paper we report on the background and contents of our new course „Environmental Physics”  which was introduced into the series of normal teaching process for BSC students at Szeged University (Hungary).', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('78', 14, '2005', 'Niekoľko postrehov z pokračujúcej diskusie na tému: Meranie magnetického poľa Zeme podľa učebnice [1]', 'Some of the Observations from the Continuing Discussion: Measurement of the Earth`s Magnetic Field According to a Textbook [1]', '', 'Article', '1335-4981', '', '52', '54', 'Obzory matematiky, fyziky a informatiky', '', 'What the suggested the design of the model in the article [2] and the other topics concerning the contents of the article.', '');
