INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('81', 15, '2005', 'Priznania slávnych i menej známych', NULL, '', 'Article', '1335-4981', '', '22', '25', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('82', 15, '2005', 'Kremíkové nanokryštáliky', 'Silicon Nanocrystals', '', 'Article', '1335-4981', '', '26', '29', 'Obzory matematiky, fyziky a informatiky', '', 'The article deals with description of nanophase materials on the silicon base. Describes the standard method of creating nanocrystals by ionic implantation of the silicon dioxide layers into the silicon base. It deals also with possibilities of using such nanocrystals in new computer technologies, communication technologies as well as producing LED diodes etc.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('83', 15, '2005', 'Metódy získavania a spracovania snímkov v medicíne', 'Methods of Obtaining and Elaboration of the X-ray in Medicine', '', 'Article', '1335-4981', '', '30', '45', 'Obzory matematiky, fyziky a informatiky', '', 'The paper is dedicated to the 110th anniversary of discovery of the X-rays, as well as to highlighting the importance and social value of physical discoveries in our everyday life. In the paper we deal with the description of physical principles of screening methods used in medicine. These include, alongside the X-rays, various tomographic methods and the most recent method of nuclear magnetic resonance. The content of this paper is in accordance with the fact that the year 2005 has been declared as the year of physics.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('84', 15, '2005', 'Elektromagnetická indukcia v rámiku s pohyblivou stranou', 'Electromagnetic Induction in the Frame with the Mobile Side', '', 'Article', '1335-4981', '', '46', '52', 'Obzory matematiky, fyziky a informatiky', '', 'A calculation of the induced current and velocity of the metallic rod in the frame circuit, which rests in a horizontal plane is presented. Magnetic flux is perpendicular to the frame and system is isolated. Induced current flows through the loadings R, C, L, RC and RL.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('85', 15, '2005', 'Meranie kapilárnej konštanty pomocou úzkej štrbiny', 'Measuring of a Capillary Constant by Means of a Narrow Gap', '', 'Article', '1335-4981', '', '53', '54', 'Obzory matematiky, fyziky a informatiky', '', 'About the possibilities of comparison of measuring the capillary constant by the means of a capillary and a narrow gap.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('86', 15, '2005', 'Zakladatelia slovenskej teoretickej fyziky', 'Founders of the Slovak Theoretical Physics', '', 'Article', '1335-4981', '', '55', '62', 'Obzory matematiky, fyziky a informatiky', '', 'This paper provides a short survey of beginning of Slovak theoretical physics. Life and scientific activities of Slovak theorists Ján Fischer and Milan Petráš are described in details.', '');
