INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('98', 2, '2006', 'Loedelove diagramy v špeciálnej teórii relativity 1', 'Loedel Diagrams in Special Theory of Relativity', '', 'Article', '1335-4981', '', '32', '36', 'Obzory matematiky, fyziky a informatiky', '', 'In this work we use Loedel diagrams to present geometric derivation and explanation of the contraction of length and dilation of time.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('99', 2, '2006', 'Fyzikální poznávání světa a vzdělávání ve fyzice', 'Physical Cognition of World and Physics Education', '', 'Article', '1335-4981', '', '37', '50', 'Obzory matematiky, fyziky a informatiky', '', 'It describes an effort of people to cognize our world in its whole range – from an atomic nucleus to the most distant spheres of Universe. There are hypothesises according to which this process of cognition is realised. The process is illustrated on the basis of plenty of examples from history. The next attention is given to an effort to apply the results of the physical cognition to human activities. The last part is concentrated on the present problems that accompany physics education, including the education of future teachers of physics and engineers.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('100', 2, '2006', 'World Year of Physics 2005  Activities in Slovakia', 'World Year of Physics 2005 Activities in Slovakia', '', 'Article', '1335-4981', '', '51', '60', 'Obzory matematiky, fyziky a informatiky', '', 'In this paper are described main projects and activities held in Slovakia in the year 2005 which United Nations declared as the World year of Physics.', '');
