INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('107', 16, '2006', 'First-order phase transitions for an ensemble of finite systems', 'First-order phase transitions for an ensemble of finite systems', '', 'Article', '1335-4981', '', '24', '29', 'Obzory matematiky, fyziky a informatiky', '', 'We consider a large ensemble of identical systems in cubic volumes of various sizes. Assuming that each system exhibits a first-order phase transition with a two-phase coexistence, we discuss the cumulative effect of the finite-size effects in the constituent systems of the ensemble. Such an analysis is important in the statistical mechanical description of voltammogram spikes measured in electrochemistry.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('108', 16, '2006', 'Loedelove diagramy v špeciálnej teórii relativity 2', 'Loedel´s Diagrams in Special Theory of Relativity', '', 'Article', '1335-4981', '', '30', '35', 'Obzory matematiky, fyziky a informatiky', '', 'Our goal is to infer Lorentz transformations by using Loedel’s diagrams. The paradox of the car and garage is explored also.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('109', 16, '2006', 'Současná fyzikální věda v úlohách Fyzikální olympiády', 'Contemporary Physics Science in Problems of the Physics Olympiad', '', 'Article', '1335-4981', '', '36', '56', 'Obzory matematiky, fyziky a informatiky', '', 'It deals with problems connected with an application of elements of contemporary physics science in problems of the International Physics Olympiad (IPhO). Regarding theoretical problems it is the fact that secondary school students do not often know necessary physical and mathematical relations (they must be presented). As for experimental problems organizers are limited to a great number of devices that must be built. For this reason the problems when a participant is able to manage with limited aids. In the second part there are twenty seven examples how organizers are successful in an application of contemporary science in problems of the IPhO.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('110', 16, '2006', 'Historický vývoj a súčasný stav slovenskej fyzikálnej terminológie', 'History Development and Current State in Slovak Terminology in Physics', '', 'Article', '1335-4981', '', '57', '62', 'Obzory matematiky, fyziky a informatiky', '', 'The article deals with the history, development and current state of Slovak terminology in physics since XIX century. The influence of German, Czech, Russian and English terminologies on the Slovak terminology is commented. More attention is devoted to translation of ISO – 31 standard „Quantities an units“ and to the corresponding modifications of Slovak terminology in physics. The inconsistency in translations of several European standards with the STN ISO 31 standard is documented. The activity of  „Slovak commission on terminology in physics“ is mentioned.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('111', 1, '2006', 'Matematické nástroje', NULL, '', 'Article', '1335-4981', '', '17', '20', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('112', 1, '2006', 'A Statistical Mechanical Theory of First-order Phase Transitions on Crystalline Electrodes', 'A Statistical Mechanical Theory of First-order Phase Transitions on Crystalline Electrodes', '', 'Article', '1335-4981', '', '21', '24', 'Obzory matematiky, fyziky a informatiky', '', 'We briefly discuss a statistical mechanical theory from which voltammogram spikes observed during underpotential deposition (UPD) on electrode surfaces can be obtained. We interpret a voltammogram spike as an averaged result of a first-order phase transition taking place in each of the crystalline domains (crystals) formed on the electrode surface. This allows us to fit the theoretical voltammogram spike to experiment with very good precision. We demonstrate this with the UPD of Cu on Pt(111).', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('113', 1, '2006', 'Loedelove diagramy v špeciálnej teórii relativity 3', 'Loedel´s Diagrams in Special Theory of Relativity', '', 'Article', '1335-4981', '', '25', '31', 'Obzory matematiky, fyziky a informatiky', '', 'In this work are presented basic principles of special theory of relativity based on Loedel diagrams.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('114', 1, '2006', 'Polytropické rozpínanie ideálneho plynu podľa kinetickej teórie', 'Polythropic Expansion of the Ordinary Gas by the Kinetic Theory', '', 'Article', '1335-4981', '', '32', '35', 'Obzory matematiky, fyziky a informatiky', '', 'Our aim is to infer the polytropic equation. Polytropic equations are used by nature for a variety of forces where the force is inversely proportional to an integer power of the distance from the source (gravitational, electrostatic, van der Waals, etc).', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('115', 1, '2006', 'Termodynamika piestového parného stroja', 'Thermodynamics of the Steam Engine', '', 'Article', '1335-4981', '', '36', '42', 'Obzory matematiky, fyziky a informatiky', '', 'The paper deals with the first steam engine invented by D. Papin. For instruction purpose, the engine was improved with the valve. Description of the principle and operation of these engines is shown as well as derivating the efficiency of the improved engine.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('116', 1, '2006', 'Samostatné poznávanie na príklade matematického kyvadla', 'Individual Getting to Know on the Example of the Mathematical Pendulum', '', 'Article', '1335-4981', '', '43', '49', 'Obzory matematiky, fyziky a informatiky', '', 'The article describes a series of lessons, in which students should find themselves out, which factors influence period of oscillation of a pendulum. At the beginning a task is set: „What is the period of oscillation of 4,5 m long pendulum with the weight of 1,5 kg?“ Students suggest methods for the problem solution, formulate and verify their hypotheses. After a year students solve another problem: „What should be done with pendullum clock, that is gaining time?“ The students, who were investigating and solving the problem of pendullum period of oscillation individually, solved the latter task much better than those, who teased out the knowledge in a „traditional“ way.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('117', 1, '2006', 'Štatistická fyzika v príkladoch a úlohách, Daniel Kluvanec, Igor Medveď, Fakulta prírodných vied Univerzity Konštantína Filozofa v Nitre', NULL, '', 'Article', '1335-4981', '', '69', '70', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('118', 1, '2006', 'Cesta do hlbín matematikovej duše, Peter Vrábel: Heuristika a metodológia matematiky. Fakulta prírodných vied Univerzity Konštantína Filozofa, Nitra 2005.', NULL, '', 'Article', '1335-4981', '', '71', '72', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('119', 3, '2006', 'Utilisation of Computers in Holographic Interferometry', 'Utilisation of Computers in Holographic Interferometry', '', 'Article', '1335-4981', '', '26', '32', 'Obzory matematiky, fyziky a informatiky', '', 'The paper deals with possibilities of using computer technology in holographic interferometry. The authors mainly describe analysis of holographic interferograms, emphasizing their own  image processing software.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('120', 3, '2006', 'Vyučovanie fyziky na základných a stredných školách v druhej polovici 19. storočia a v súčasnosti', 'Teaching Physics in the Primary and Secondary School in the Second Half of the 19th Century and at Present', '', 'Article', '1335-4981', '', '33', '41', 'Obzory matematiky, fyziky a informatiky', '', 'The article analyses and compares the process of teaching physics at secondary schools in the second half of 19th century and today. The author concentrates on the development of curriculum in physics – its content and goals and is based on a through study of historical and teaching materials.', '');
