INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('128', 17, '2007', 'The Mathematical Explorer alebo informácia o jednom zaujímavom projekte', 'The Mathematical Explorer or the Information about Some Interesting Project', '', 'Article', '1335-4981', '', '29', '41', 'Obzory matematiky, fyziky a informatiky', '', 'The Mathematical Explorer is an exploration into some of the most interesting mathematics in history and is suitable for anyone who has been intrigued by mathematics and its applications, including hobbyists and students. It contains expository text, illustrations, and interactive examples on a variety of mathematical topics. The treatment of each topic is designed to be educational as well as entertaining; it includes a clear explanation of the important concepts along with fascinating cultural and historical details.
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('129', 17, '2007', 'How massive is the black hole at the centre of our Galaxy?', 'How Massive is the Black Hole at the Centre of our Galaxy? ', '', 'Article', '1335-4981', '', '43', '51', 'Obzory matematiky, fyziky a informatiky', '', 'Using the formula for calculation of roots of a quadratic equation, Pythagorean theorem, Kepler\'s laws and observed data, we show that the mass of the black hole at the centre of our Galaxy is more than 3 million Sun masses.
