INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('144', 18, '2007', 'Termodynamika ako základ moderného popisu reálneho sveta', 'Thermodynamics as the Base of the Modern Description of Real Universe', '', 'Article', '1335-4981', '', '55', '56', 'Obzory matematiky, fyziky a informatiky', '', 'The author has presented thermodynamics as an important part of modern physics. Thermodynamics is a theoretical base for descriptive occurrences and processes above world and into universe too. At present we pay scant attention to the courses of school Physics. Pupils and students consider thermodynamics as a hard discipline too. If teachers teach thermodynamics using the tasks and examples from the life around us, situation will probably improve.', '');
