INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('160', 21, '2008', 'Obecné principy fyziky', 'General Principles of Physics', '', 'Article', '1335-4981', '', '48', '66', 'Obzory matematiky, fyziky a informatiky', '', 'The article systematizes a process of a physical cognition (phases: an experiment, a hypothesis, a law of physics, a principle, a physical theory) and concentrates on general principles on which the physics is based. It deals with variational principles of physics – the principle of least action in classical mechanics, in  Maxwell´s theory of electromagnetic field and optics. It follows up with an essay about principles of conservation in classical physics, points at their connection with a symmetry in nature and formulates the theorem of Noether and from it resulting principles of conservations of energy, of momentum and angular momentum. The final parts are dedicated to the principles of thermodynamics and general principles and principles of conservation in relativistic and quantum physics.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('161', 21, '2008', 'Oko - najviac zaťažený zmyslový orgán', 'Eye – the Mostly Overburdened Sense Organ', '', 'Article', '1335-4981', '', '67', '69', 'Obzory matematiky, fyziky a informatiky', '', 'The article analyses the main conditions of the human eye sight protection at the work with the screen units.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('162', 22, '2008', 'Matematika a voľby II: Volebné kvocienty a delitele', 'Mathematics and Election II: Electoral Quotients and Divisors', '', 'Article', '1335-4981', '', '5', '18', 'Obzory matematiky, fyziky a informatiky', '', 'In the paper some standard apportionment procedures (largest remainder methods and divisor methods) are introduced and explained.
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('163', 22, '2008', 'Role of ground and building material in radioactive background emission', 'Role of ground and building material in radioactive background emission', '', 'Article', '1335-4981', '', '33', '37', 'Obzory matematiky, fyziky a informatiky', '', 'The knowledge of radioactive dose reaching the human body is very important for healthy condition of people. Both natural and artificial radioactive emission are present in our everyday life causing activity load about 2.5 mSv per year, including the influence of radon (1 mSv). Our study deals with the influence of building materials on environmental radioactive load coming from weathering, acid volcanic and loamy ground stones. We have also considered the emission from atomic plants and facilities of agricultural origin. We have concluded that the highest radioactivity is caused by bricks due to their high clay contents; cement has lower radioactivity, while sand and building stones have also a relatively low activity. The activity might be changed due to the building methods, seasons, and also temperature. The investigation in the future is necessary to choose proper building materials.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('164', 22, '2008', 'Doktorandská škola z fyziky na Univerzite Eötvösa Loránda otvára PhD – program z Teórie vyučovania fyziky pre stredoškolských profesorov fyziky', 'Doctoral School from Physics at Eötvös Lorand University opens PhD – Programme of Theory of Teaching Physics for the Secondary School Teachers of Physics', '', 'Article', '1335-4981', '', '38', '53', 'Obzory matematiky, fyziky a informatiky', '', 'The proposed article (published originally in Hungarian see [1]) analyses the need of opening an individual PhD program in Methodology of Physics Teaching for teachers of physics in Hungary. At the same time it gives a detailed information on the first three-year-cycle which was commenced in September in the academic year of 2007/2008 at the University of Lorand Eötvös in Budapest.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('165', 22, '2008', 'Poznámky k cieľom fyzikálneho vzdelávania', 'Notes of the Goals of Physics Education', '', 'Article', '1335-4981', '', '54', '62', 'Obzory matematiky, fyziky a informatiky', '', 'Some Remarks about Goals of Physics Education. The article deals with goals of physics education. Comes out from official European documents (DG Education and DG Research). Divides physics education to formal and informal. Points specific issues in Slovakia and presents two possible ways of progress. Suggested is new conception (new in Slovakia, present already in many other education systems) based on goals presented by organizations such as UNESCO, IBO, OECD, based on harmonious goals-oriented development of scientific literacy of pupils and students. Further discussion on this topic is proposed.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('166', 22, '2008', 'Max Planck - hľadač absolútnych predstáv', 'Max Planck – Searcher of the Absolute Images', '', 'Article', '1335-4981', '', '63', '67', 'Obzory matematiky, fyziky a informatiky', '', 'Brief biographical profile of distinguished physicist.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('167', 22, '2008', 'Krátke zamyslenie nad úlohou: pád loptičky z výšky desať metrov', 'A Short Reflection on the Task: The Fall of the Tennis Ball from the Height of 10 Meters', '', 'Article', '1335-4981', '', '68', '70', 'Obzory matematiky, fyziky a informatiky', '', 'A short reflection on the task: The fall of the tennis ball from the height of 10 metres Were the students while studying the fall of the table tennis ball from the height of 10 meters condemned in advance to the failure?', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('168', 23, '2002', 'O matematice a jejím vyučování', 'Mathematics and Mathematics Education', '', 'Article', '1335-4981', '', '1', '8', 'Obzory matematiky, fyziky a informatiky', '', 'How to conceive mathematics as the basis of mathematics education? The role of calculation and the mathematical structures. Mathematics as the search for structures. Mathematics as the search for structures and patterns that bring order and simplicity to our universe. Dual nature of mathematics: it is both an independent discipline valued for precision and intrinsic beauty, and it is a rich source of tools for the world of applications (Griffith). A serious threat to the very life of science is implied in the assertion that mathematics is nothing but a system of conclusions drawn from definitions and postulates (Courant). Mathematics and the constructivist approach to mathematics teaching. Some examples.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('169', 23, '2002', 'Súčinové magické štvorce a kocky', 'Multiplicative Magic Squares and Cubes', '', 'Article', '1335-4981', '', '9', '16', 'Obzory matematiky, fyziky a informatiky', '', 'A multiplicative magic square is a square matrix containing different natural numbers such that the product of the numbers along every row, column and two diagonals is the same. A multiplicative magic cube is defined in a similar way. In this paper we give several ways to construct multiplicative magic squares and cubes. We end this paper by stating some original problems.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('170', 23, '2002', 'Extremálne obsahy na kružnici I.', NULL, '', 'Article', '1335-4981', '', '17', '19', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('171', 23, '2002', 'Macromedia Flash 5', 'Macromedia Flash 5', '', 'Article', '1335-4981', '', '20', '30', 'Obzory matematiky, fyziky a informatiky', '', 'Macromedia Flash 5 is the key to creating and designing graphics, animations, presentations and Web sites. This program builds animations on the vector based and has own internal scripting language - ActionScript. The aim of the paper is to present this interesting program - Macromedia Flash 5.
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('172', 23, '2002', 'Pohľad na vyučovanie matematiky na stredných školách SR cez optiku medzinárodných súťaží', NULL, '', 'Article', '1335-4981', '', '31', '38', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('173', 23, '2002', 'Názory študentov gymnázia na vyučovanie fyziky (2. časť)', 'Opinion of Students of Grammar Schools on Teaching of Physics (2nd part)', '', 'Article', '1335-4981', '', '39', '49', 'Obzory matematiky, fyziky a informatiky', '', 'The paper presents the 2nd part of the analysis of investigation results that has been carried out in the 2nd periodof the school year of 2000/2001 in 9 graduiting classes of four & eight year grammar schools in towns of Levice, Nitra, Šahy and Žilina with the number of respondents 259. The investigation has been aimed on opinion of students of grammar schools on teaching of physics. The results of this investigation can be utilizet in pedagogical practice at the selection of methods and forms of the teachers activities in subject of physics as well as at the inplementation of innovation intentions in curriculum of physics.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('174', 24, '2002', 'AG-nerovnosť', 'AG – inequality', '', 'Article', '1335-4981', '', '4', '11', 'Obzory matematiky, fyziky a informatiky', '', 'The paper is devoted to the AG-inequality. The proof, which is based on approach of Pinter and Hegedüs [4], and some applications are presented.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('175', 24, '2002', 'Logika vo vyučovaní matematiky', 'Logic in Teaching of Mathematics', '', 'Article', '1335-4981', '', '12', '23', 'Obzory matematiky, fyziky a informatiky', '', 'This article deals with an issue of logical thinking of pupils of primary schools. We present results of an experiment from this field. Pupils were asked to solve different syllogisms. According to their answers we analyzed their thinking processes and classified them by certain phenomenon. In the end we show possibilities of further research.
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('176', 24, '2002', 'Jeremy J. Gray: Linear Differential Equations and Group Theory from Riemann', NULL, '', 'Article', '1335-4981', '', '24', '29', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('177', 24, '2002', 'Súprava z geometrickej optiky GON+', 'Demonstration Set for the Geometrical Optics GON+', '', 'Article', '1335-4981', '', '29', '37', 'Obzory matematiky, fyziky a informatiky', '', 'Autor of the paper has created a new set of teaching aids (GON+) to support physics education at all levels (primary, secondary, teachers training). The set contains untraditional optical elements (“they are made” from the air and surrounded by glass), which allow to show a lot of suprising and interesting experiments. Some of these experiments are introduced in this paper. In addition it is possible to do quantitative analysis of the data obtained from experiments by measurement distances, radiuses, sizes etc.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('178', 24, '2002', 'Prostriedok na realizáciu „terénnych experimentov“', 'Facility for the Realisation of “Terrain Experiments”', '', 'Article', '1335-4981', '', '38', '43', 'Obzory matematiky, fyziky a informatiky', '', 'The article presents a new educational measuring set CBL2, as an instrument at elementary measurements in exteriors and classrooms. It presents its components. At the end of this article is demonstration of use the CBL2.
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('179', 24, '2002', 'Jadrová energetika a životné prostredie', 'Nuclear Energetics versus Environment', '', 'Article', '1335-4981', '', '44', '49', 'Obzory matematiky, fyziky a informatiky', '', 'Currently, the nuclear energetic has a distinguished and solid place in the field of electric energy production. The influence of radiation produced by the nuclear power station (NFS) on environment is being continuously monitored. However, NPSs contribute to the increase of the environment radioactivity to a small extent. A comparison between irradiation limiting values caused by NPSs and radioactivity natural background is performed as well as their influence on a human is considered.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('180', 24, '2002', 'Jakub Pribicer: Tractatus de Cometa', NULL, '', 'Article', '1335-4981', '', '50', '53', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('181', 24, '2002', 'Feynmanova stratená prednáška v dvoch dieloch', NULL, '', 'Article', '1335-4981', '', '62', '64', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('182', 25, '2002', 'Chyba v interakcii učiteľ - žiak', 'Error in Interaction Teacher-Student', '', 'Article', '1335-4981', '', '1', '14', 'Obzory matematiky, fyziky a informatiky', '', 'In one-to-one teaching, primary teacher Eva tries to explain to Peter, Grade 3 the topic \"large numbers\" using the textbook [3]. Eva\'s protocols of this experimental teaching are analysed and evaluated. The phenomenon of thr student\'s mathematical and the teacher\'s didactical mistakes is the centre of analyses. Several suggestions of how to help a teacher to overcome his/her didactical mistakes are given.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('183', 25, '2002', 'Poznámka o limitách', 'A Remark on Limits', '', 'Article', '1335-4981', '', '15', '19', 'Obzory matematiky, fyziky a informatiky', '', 'In the first part of this paper we study limits of real sequences. In the second part we study limits of functions of several variables.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('184', 25, '2002', 'Pravdepodobnosť a symetria', 'Probability and Symmetry', '', 'Article', '1335-4981', '', '20', '29', 'Obzory matematiky, fyziky a informatiky', '', 'Construction and research of probability spaces is the objective of theory of probability. Certain method of construction of such spaces is discussed in this paper, focusing on symmetries as the base for consequences related to probability. Symmetries allow us to rationalize \"doing mathematics\", while they reduce complicated calculations to simple conclusions. The author conjectures that the ideas presented here can be successfully adopted for use in probability classes in different grades.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('185', 25, '2002', 'Význam matematiky a fyziky pre spoločnosť', 'The Importance of Mathematics and Physics for the Society', '', 'Article', '1335-4981', '', '30', '33', 'Obzory matematiky, fyziky a informatiky', '', 'Impact of Mathematics and Physics on Society. Impact of mathematics and physics on society consists in tree areas - in their applicability to technical problems, in their influence on culture of thought and in their influence on ethics.
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('186', 25, '2002', 'Názory, postoje a reakcie stredoškolského učiteľa na nové učebnice matematiky pre gymnáziá a SOŠ', '', '', 'Article', '1335-4981', '', '34', '36', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('187', 25, '2002', 'Rozvoj fyzikálneho myslenia žiakov pomocou zaujímavých a poučných experimentálnych úloh', 'Development of the Physical Thoughts via Interesting and Edifying Experimental Problems', '', 'Article', '1335-4981', '', '37', '43', 'Obzory matematiky, fyziky a informatiky', '', 'The Physical Thinking Development by Means of Interesting and Edifying Experimental Tasks The progress of the mankind was directly determined by discoveries of the physics and by those implementation into production, and into our daily life. The school physics have here inevitable great role by education. Physics is important, but we are witnesses, that it is not very favourable subject nowadays. It requires seemingly a special way of thinking or any inborn aptitude. We have here many reasons for a making the way of learning more accessible and attractive. One nice way is here to use more physical experiments, to make their analysis, to promote motivational tasks and to enhance discussions in groups. This paper intents to show nearer look into the possibility to involve posters and Power-Points as main bearer of instruction, how to perform large number of incentive experiments. Many times (in the emergency cases) can be concerning posters and power-points useful utilised also without real experimentations. To this aim serve dynamical pictorial delineatinos with adequate eloquent labelling with connected short textual description, instructions, explanations and mention of possible practical using. This contribution intents to show some examples of experiments with incentive odour. Many impressive arranged and sophisticated posters and Power-Points can run, be displayed in school vestibuls and effects there for a longer time, and change the minds of learners just in wished direction.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('188', 25, '2002', 'Program pokročilej fyziky na stredných školách v USA', NULL, '', 'Article', '1335-4981', '', '44', '46', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('189', 25, '2002', 'Kalendár významných osobností fyziky v roku 2002', NULL, '', 'Article', '1335-4981', '', '59', '61', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('190', 26, '2002', 'Súčty Sk(n) a Bernoulliho čísla', 'Sums and Bernoulli Numbers', '', 'Article', '1335-4981', '', '1', '9', 'Obzory matematiky, fyziky a informatiky', '', 'We consider Bernoulli numbers in connecrions with sums Sk(n)=1^k+2^k+...+n^k.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('191', 26, '2002', 'Kvadratické rovnice a nerovnice', 'The quadratic Equations and Unequalities', '', 'Article', '1335-4981', '', '10', '18', 'Obzory matematiky, fyziky a informatiky', '', 'Most of the quadratic equations and inequalities you will encounter in problem books can be solved by elementary methods.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('192', 26, '2002', 'Úvaha o jednom ekonomickom príklade', 'Reflection on one economic Example', '', 'Article', '1335-4981', '', '19', '22', 'Obzory matematiky, fyziky a informatiky', '', 'In this article we discuss solution of a problem given at an entrance examination. We show that using the right mathematical modeling of the economic terms in the problem it is possible to obtain more interesting and realistic solution.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('193', 26, '2002', 'Poškolácke úlohy', NULL, '', 'Article', '1335-4981', '', '23', '26', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('194', 26, '2002', 'Prehľad životopisných údajov významných matematikov', NULL, '', 'Article', '1335-4981', '', '27', '31', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('195', 26, '2002', 'Matematika a teológia', 'Mathematics and Theology', '', 'Article', '1335-4981', '', '32', '39', 'Obzory matematiky, fyziky a informatiky', '', 'We consider the influence of monotheistic theology on the development of western mathematics. We illustrate this influence on notions of infinity, probability, variable, space, and motion.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('196', 26, '2002', 'Numerická matematika a nový prístup k jej výučbe', 'Numerical Mathematics and new Access to its Teaching', '', 'Article', '1335-4981', '', '40', '43', 'Obzory matematiky, fyziky a informatiky', '', 'In the paper we attempt to valuate a new conception of teaching elements of numerical mathematics at FME SUT in Bratislava. It is confirmation of experimental teaching in the basic course of mathematics, with the aid of the programming system Mathematica. Investigated hypotheses and obtained results are presented in my paper.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('197', 26, '2002', 'Úvaha o súčasnom stave školskej fyziky na Slovensku', 'Reflection of the Present State of the School Physics in Slovakia', '', 'Article', '1335-4981', '', '44', '49', 'Obzory matematiky, fyziky a informatiky', '', 'Reflection of the present state of the school physics in Slovakia Present state of the school physics according to the valid documents. Proposals for the changes in the intention of the National program of education in Slovakia.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('198', 26, '2002', 'Modelovanie zmyslového orgánu určeného na priestorovú orientáciu', 'Modelling of a Sense-Organ designed for the Space Orientation', '', 'Article', '1335-4981', '', '50', '61', 'Obzory matematiky, fyziky a informatiky', '', 'Presented article deal with integration the science knowledge in the area school physics and biology in form interesting observations (P), tasks (U), and measurements (M).', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('199', 27, '2001', 'Nelineárne obyčajné diferenciálne rovnice vo fyzike', 'Nonlinear Ordinary Differential Equations in Physics', '', 'Article', '1335-4981', '', '1', '7', 'Obzory matematiky, fyziky a informatiky', '', 'In this paper four boundary value problems for nonlinear ordinary differential equations are introduced: 1. Emden-Fowler problem in astrophysics, 2. Thomas-Fermi problem in atomic physics, 3. Blasius problem in fluid mechanics, 4. Bending of the beam. Firstly, for each problem there is a short physical explanation without any detailed mathematical derivation. Then the plots of approximate solutions are obtained by computer using the program Mathematica.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('200', 27, '2001', 'Veta o troch dotyčniciach paraboly z pohľadu projektívnej a afinnej geometrie', 'Three Tangens Theorem in View of the Projective and Affine Geometry', '', 'Article', '1335-4981', '', '8', '15', 'Obzory matematiky, fyziky a informatiky', '', 'Three tangent theorem in view of the protective and affine geometry. Three tangent theorem is the essential theorem for de Casteljau algorithm used in computational geometry. The proof of this theorem is omitted in most of the literature. Presented paper contains three different proofs of this theorem. The first uses the method of projective geometry to prove four tangent theorem and then the three tangent theorem as its corollary. The second proof uses central projection of conic sections. The third proof is an affine analytic proof.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('201', 27, '2001', 'Neutrína včera, dnes a zajtra', 'Neutrino Yesterday, Today and Tomorrow', '', 'Article', '1335-4981', '', '25', '31', 'Obzory matematiky, fyziky a informatiky', '', 'Neutrino is a fundamental particle, emitted in various nuclear and particle physics processes. It is the most elusive particle, known for scientists and this property makes it to be almost invisible. We briefly mention history of neutrino and its physical properties. We concentrate especially on the problem of its mass. Neutrinos had been taken as massless particles for a long time. Many recent experiments find so called neutrinos oscillations. The observed oscillations prove that the mass of neutrinos is not zero. We discuss these experiments and their results (especially from Japan Super-Kamiokande and KamLAND). Oscillations can solve problems in other fields of physics. We briefly deal with long standing solar neutrino problem as well as with the relations of neutrinos and dark matter.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('202', 27, '2001', 'Pevné, či tuhé skupenstvo', '', '', 'Article', '1335-4981', '', '32', '38', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('203', 27, '2001', 'Smädný bocian a fyzika', 'Thirsty Stork and Physics', '', 'Article', '1335-4981', '', '39', '43', 'Obzory matematiky, fyziky a informatiky', '', 'There are many toys which are based on a certain physical phenomenon or law. In the paper the analysis of the physical principle of one of them – “thirsty stork” is presented. This toy can by used to demonstrate these physical phenomena and to encourage the interest of students in the taught topic.
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('204', 27, '2001', 'Einsteinov valec', NULL, '', 'Article', '1335-4981', '', '44', '47', 'Obzory matematiky, fyziky a informatiky', '', '', '');
