INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('210', 28, '2001', 'Poškolácke úlohy', NULL, '', 'Article', '1335-4981', '', '28', '30', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('211', 28, '2001', 'Dlhá cesta k atómovému rozlíšeniu', 'Long Way to Atomic Resolution', '', 'Article', '1335-4981', '', '31', '39', 'Obzory matematiky, fyziky a informatiky', '', 'We follow a development in the field of microscopy from 16th to the 20th century. Article starts with optical microscopy. We discuss its fundamental limit on the resolution. It has origin in the wave nature of light. The same limit holds for next generation of microscopes which make use of different kinds of elementary particles. New possibilities appear with Binning\'s and Rohrer\'s scanning tunneling microscope (STM). The principles of STM are explained in the second part of article. Atomic resolution was reached firstly with this approach. In can be also used as a tool for manipulation with individual atoms. On the other hand STM is constrained only to conducting samples. The third part of article is concerned with the atomic force microscope (AFM). AFM arise from the STM and it is not limited to the conducting samples. We summarise other advantages of this method, particularly paying attention to the problems of interpretation of the experimental data.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('212', 28, '2001', 'K spracovaniu výsledkov merania fyzikálnych veličín', NULL, '', 'Article', '1335-4981', '', '40', '42', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('213', 28, '2001', 'Opakovanie učiva zákazom', NULL, '', 'Article', '1335-4981', '', '43', '45', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('214', 29, '2001', 'Bod a trojuholník', 'Point and Triangle', '', 'Article', '1335-4981', '', '12', '20', 'Obzory matematiky, fyziky a informatiky', '', 'In this article we shall mention one interesting relation among point, triangle and incrible circle of triangle. We shall utilize knowledge from geometry as the circuit angle, the section angle, the sum of angles in triangle, properties of the sine function, the low of sine and the Ceva theorem.
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('215', 29, '2001', 'Pythagorova veta - zaujímavosti a príklady', 'Pythagorean Theorem', '', 'Article', '1335-4981', '', '21', '24', 'Obzory matematiky, fyziky a informatiky', '', 'The aim of this contribution is Pythagoras theorem and its application. The interesting examples which are useful for development of mathematical thinking are given.', '');
