INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('218', 29, '2001', 'Globálna rádioaktivita a jej vplyv na človeka', 'Global Radioactivity and its Influence on Human', '', 'Article', '1335-4981', '', '38', '49', 'Obzory matematiky, fyziky a informatiky', '', 'The radioactive pollution of environment is caused both by the natural (cosmic radiation and radon) and human made (nuclear bombing effects, nuclear power stations) resources. Many researchers (readers) are interested in study of the ways radionuclids are transferred to a human as well as the ionising radiation influence on it. The (consequences of the) low level surrounding radioactivity influence on a human can not be easily predicted because it needs a continuous (and long lasting) monitoring of environment.
