INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('221', 31, '2001', 'Pozor na l\'Hospitala!', 'Be Careful with l\'Hospital!', '', 'Article', '1335-4981', '', '1', '15', 'Obzory matematiky, fyziky a informatiky', '', 'The article is a short reviey of possible mistakes that can be done using the l\'Hospital rule.', '');
