INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('223', 31, '2001', 'Polarizované svetlo a jeho biostimulačné účinky na organizmus', 'Biostimulation Effect of Polarized Light on the Human Organism', '', 'Article', '1335-4981', '', '23', '30', 'Obzory matematiky, fyziky a informatiky', '', 'The authors in this review presents their first opinions and results confronted with the literature sources used by biostimulation effect of polarized light (VIP - phototherapy) for a support of classical rehabilitation by selected sample of the medical indications.
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('224', 31, '2001', 'Overovanie rozumovo - výkonových charakteristík fyzikálnych úloh', 'Proof of the Rational – Efficient Characteristics', '', 'Article', '1335-4981', '', '31', '38', 'Obzory matematiky, fyziky a informatiky', '', 'Proof of the rational - efficient characteristics of physics tasks.
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('225', 31, '2001', 'Názory študentov gymnázia na vyučovanie fyziky (1. časť)', 'Opinions of students of grammar school on teaching of physics', '', 'Article', '1335-4981', '', '39', '46', 'Obzory matematiky, fyziky a informatiky', '', 'The paper presents the 1st part of the analysis of investigation results that has been carried out in the 2nd period of the school year of 2000/2001 in 6 graduating classes of four & eight year grammar schools in towns of Levice, Nitra, Šahy and Žilina with the number of respondents 259. The investigation has been aimed on opinion of students of grammar schools on teaching of physics. The results of this investigation can be utilised in pedagogical practice at the selection of methods and forms of the teachers activities in subject of physics as well as at the implementation of innovation intentions in curriculum of physics.
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('226', 31, '2001', 'Literatura k podpoře soutěže fyzikální olympiády v České republice', NULL, '', 'Article', '1335-4981', '', '47', '53', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('227', 32, '2000', 'Tri Jasné dni v novembri 1999', NULL, '', 'Article', '1335-4981', '', '1', '13', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('228', 32, '2000', 'O dobrom usporiadaní a axióme výberu', NULL, '', 'Article', '1335-4981', '', '14', '24', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('229', 32, '2000', 'Nielen o indickom násobení', '„Indian“ Multiplication from the Teaching Point of View', '', 'Article', '1335-4981', '', '25', '32', 'Obzory matematiky, fyziky a informatiky', '', '“Indian” multiplication does not belong to the generally used algorithms of multiplication in our schools. It is a pity because it has many advantages compared with the “classic” multiplication. This article not only calls attention to this fact but also offers several non-standard problems related to this topic. It is illustrated by concrete examples from the teaching practice.
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('230', 32, '2000', 'Základy modernej fyziky dneška I: Všeobecná teória relativity (podľa knihy E. F. Taylora a J. A. Wheelera „Exploring Black Holes: Introduction to General relativity“)', 'Fundamentals of Contemporary Physics I: General Theory of Relativity (After E. F. Taylor and J. A. Wheeler “Exploring Black Holes: Introduction to General relativity”)', '', 'Article', '1335-4981', '', '33', '46', 'Obzory matematiky, fyziky a informatiky', '', 'The new method how to teach general relativity without tensors using only elementary calculus used recently by E. F. Taylor and J. A. Wheeler in their book Scouting Black Holes is described here. Their tour through general relativity begins with postulating the Schwarzschild metric. Then using the Principle of Extremal Aging and the metric, constants of motion — energy and angular momentum — are derived. Later on the way to compute the trajectory of an orbiting satellite around the black hole is described briefly. At the end precession of the perihelion of Mercury is computed without solving any differential equations. Also the advantages and disadvantages of this treatment of General relativity are discussed.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('231', 32, '2000', '(Ne)bojme sa žiarenia', '(Do not) be Afraid of Radiation', '', 'Article', '1335-4981', '', '47', '50', 'Obzory matematiky, fyziky a informatiky', '', 'The change in the estimation of radiation danger is presented. The basic dosimetric units and the current limits of irradiation are introduced. Some interesting facts are mentioned, supporting the tendency to shift the upper limits of equivalent dosis for man to higher values. The article of Z. Jaworowski (Physics Today, Sept. 1999) was the main source for this contribution.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('232', 32, '2000', 'Školské experimenty so sondou teploty v systéme IP Coach', 'School Experiments with the Temperature Probe in the System of IP Coach', '', 'Article', '1335-4981', '', '51', '55', 'Obzory matematiky, fyziky a informatiky', '', 'Microcomputer-based laboratory means a new teaching environment that enables students activly construct their science understanding. In the article we describe two examples of experiments in this environment using temperature probe concerning thermal volumetric expansion of water, that can be performed as a student\'s laboratory exercise.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('233', 32, '2000', 'Netradičná úloha - nekonečná rovinná elektrická sieť rezistorov', 'Unconventional Problem – Infinite Planar Electrical Net of Resistors', '', 'Article', '1335-4981', '', '56', '58', 'Obzory matematiky, fyziky a informatiky', '', 'General principles of the comission for the preparation of physics problems in PhO. Example: Text and solution of the problem \"Infinite planar electrical net of resistors\"', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('234', 32, '2000', 'Výsledky overovania vzdelávacieho štandardu z fyziky pre gymnázium (štvorročné štúdium)', 'Results of the Verification of the Educational Standard in Physics at Grammar Schools (Four-Years Course)', '', 'Article', '1335-4981', '', '59', '70', 'Obzory matematiky, fyziky a informatiky', '', 'The contribution in forms about aims, methodics, course and results of the verification of the educational standard in physics for gymnasium with four-year study, which was carried outt in the school years 1996/97 - 1998/99 under the direction and coordination of I lie National Institute for Education in Bratislava at fourteen gymnasia in the Slovak Republic.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('235', 33, '2000', 'Konštrukcia magických p-rozmerných kociek', 'A Construction of Magic p-dimensional Cubes', '', 'Article', '1335-4981', '', '19', '29', 'Obzory matematiky, fyziky a informatiky', '', 'Magic squares have fascinated people throughout centuries. The first references to magic squares can be found in ancient Chinese and Indian literature. The reader can find up-to-date information in many web-pages. A generalisation of a magic square is a magic p-dimensional cube. A magic p-dimensional cube of order n is a p-dimensional matrix containing natural numbers 1 ,..., n^p such that the sum of the numbers along every row and every diagonal is the same. Probably the first mentioned magic cube appeared in a
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('236', 33, '2000', 'QUO VADIS MATEMATIKA  O kríze matematiky a možných východiskách', '', '', 'Article', '1335-4981', '', '30', '36', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('237', 33, '2000', 'Základy modernej fyziky dneška II: Kvantová mechanika (podľa knihy R. P. Feynmana: QED - The Strange Theory of Light and Matter)', 'Fundamentals of Contemporary Physics II: Quantum Mechanics (After R. P. Feynman: QED – The Strange Theory of Light ond Matter)', '', 'Article', '1335-4981', '', '37', '45', 'Obzory matematiky, fyziky a informatiky', '', 'Logic line of introductory course of quantum physics is presented. The course is based on Feynman\'s sum-over-paths theory and now is being offered by E.F. Taylor for high-school teachers and other students at the MIT in the USA. Vector algebra and, high-school mathematics are all the mathematics needed (no partial differential equations). The treatment starts with photons, which obey the fundamental principle: Explore all paths. The basic features of light (reflection, refraction, dispersion, interference...) are analysed just using this principle together with addition of quantum arrows. The unique treatment continues with nonrelativistic description of the behaviour of electrons. First, the classical action for a segment of a path is derived. The actions together with the principle of least action provide seamless transition between quantum and classical mechanics. Then, the wave function, the propagator and description of bound states arise naturally from the application of the simple principles. Students use computers, which help them come round complicated mathematics and often provide a deeper sense of the quantum phenomena.
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('238', 33, '2000', 'Optické javy v prírode I', 'The optical Effects in the Nature I.', '', 'Article', '1335-4981', '', '46', '52', 'Obzory matematiky, fyziky a informatiky', '', 'The most beautiful demonstration of the dispersion in the nature is a rainbow. The first part of the paper describes how to originated the primary and secondary rainbow with using the knowledge of refraction and reflection of light by drops of rain in the air. In the second part of the paper is describe some type of a rainbow and more important details and information about  quality of a rainbow.
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('239', 34, '2000', 'Iteračné postupnosti lineárnych lomených funkcií I', 'Iteration Sequences of Linear Fractional Functions I.', '', 'Article', '1335-4981', '', '1', '13', 'Obzory matematiky, fyziky a informatiky', '', 'Linear fractional functions as real functions of a real variable are considered They are divided into five disjoint classes according to the number of fixed points and behaviour of the iteration sequences. A special attention is paid to the periodic points. A kind of Sharkovskii theorem is given for such functions. An application, some problems from mathematical olympiads and from problem book of mathematical analysis are solved.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('240', 34, '2000', 'Čo všetko nám prezradí jednoduchá úloha', 'What can a Siple Task Reveal', '', 'Article', '1335-4981', '', '14', '19', 'Obzory matematiky, fyziky a informatiky', '', '12-years old children are given three or four different answers to the same mathematical problem. They have to decide which of them are right and why. Their strategies of result checking are studied and analyzed.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('241', 34, '2000', 'José Ferreirós: Labyrinth of Thought A History of Set Theory and its Role in Modern Mathematics', NULL, '', 'Article', '1335-4981', '', '20', '30', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('242', 34, '2000', 'Základy modernej fyziky dneška III: Kvantová mechanika (podľa knihy E. F. Taylora: Demystifiyng Guantum Mechanics - Poodhalenie tajomstva kvantovej mechaniky)', 'Fundamentals of Contemporary Physics III: Quantum Mechanics (After E. F. Taylor: Demystifiyng Quantum Mechanics)', '', 'Article', '1335-4981', '', '31', '43', 'Obzory matematiky, fyziky a informatiky', '', 'Logic line of introductory course of quantum physics is presented. The course is based on Feynman\'s sum-over-paths theory and now is being offered by E.F. Taylor for high-school teachers and other students at the MIT in the USA. Vector algebra and high-school mathematics are all the mathematics needed (no partial differential equations). The treatment starts with photons, which obey the fundamental principle: Explore all paths. The basic features of light (reflection, refraction, dispersion, interference...) are analyzed just using this principle together with addition of quantum arrows. The unique treatment continues with nonrelativistic description of the behaviour of electrons. First, the classical action for a segment of a path is derived. The actions together with the principle of least action provide seamless transition between quantum and classical mechanics. Then, the wave function, the propagator and description of bound states arise naturally from the application of the simple principles. Students use computers, which help them come round complicated mathematics and often provide a deeper sense of the quantum phenomena.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('243', 34, '2000', 'Testovanie schopností žiakov interpretovať grafy kinematických funkcií (závislostí)', 'Testing the Student Ability to Interpret Kinematics Graphs', '', 'Article', '1335-4981', '', '44', '55', 'Obzory matematiky, fyziky a informatiky', '', 'The article deals with the importance of graphs in physics teaching and the construction and analysis of a test that would evaluate student ability to interpret kinematics graphs like position, velocity and acceleration versus time graphs. For this particular study, data from 518 students at the secondary and college level was collected and analyzed.
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('244', 34, '2000', 'Krajské kolo fyzikálnej olympiády Veľký Krtíš ... 3. kolo FO - kategória E 14. mája 1999 (piatok) (stručné minútové hodnotenie zážitkov súťažiacich žiakov)', NULL, '', 'Article', '1335-4981', '', '68', '70', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('245', 34, '2000', 'QED - Nezvyčajná teória svetla a látky - Richard P. Feynman', NULL, '', 'Article', '1335-4981', '', '71', '72', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('246', 34, '2000', 'Iteračné postupnosti lineárnych lomených funkcií II', NULL, '', 'Article', '1335-4981', '', '1', '14', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('247', 35, '2000', 'Od paraboly k inverznej funkcii', 'From Parabola to Inverse Function', '', 'Article', '1335-4981', '', '15', '20', 'Obzory matematiky, fyziky a informatiky', '', 'The aim of the paper is to present the usefulness of graphical analysis applied on solving of equations.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('248', 35, '2000', 'O nadprirodzenej korytnačke, magických štvorcoch a kockách', 'On a Divine Turtle, Magic Squares and Cubes', '', 'Article', '1335-4981', '', '21', '34', 'Obzory matematiky, fyziky a informatiky', '', 'Magic squares belong to the oldest mathematical amusements. A magic square is a square array of integers in which the numbers in rows, columns, and diagonals have the same sums respectively. Its natural generalization yields to a magic cube. Magic squares have played various roles in the mathematics classroom: as a motivational device, as a problem-solving venture, and as an alternative way to review content. Magic squares can be used to formulate interesting problems which can be solved in terms of computers therefore they are a good device for introducing computers to children. In this paper we formulate several problems related to magic squares and cubes and establish a simple algorithm for their constructions.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('249', 35, '2000', 'Kvantová mechanika - Einstein alebo Bohr?', 'Quantum Mechanics – Einstein or Bohr?', '', 'Article', '1335-4981', '', '35', '45', 'Obzory matematiky, fyziky a informatiky', '', 'Difficulties associated with quantum mechanics and traditional Copenhagen interpretation are discussed here. The most commonly accepted Copenhagen interpretation of quantum mechanics with it\'s physical and philosophical implications are described here. We concentrate on measurement problem and the relations of reality and quantum mechanics. In the second part we describe Einstein\'s opinions about Copenhagen interpretation of quantum mechanics, which are demonstrate by famous EPR paradox. We offer Bohr\'s answer to Einstein\'s objections with some historical facts about their long dispute. The third part of the article is brief description of fundamentals of hidden variables theories. Two famous no-hidden-variables theorems - von Neuman\'s proof and Bell\'s inequalities - are mentioned. Violation of the Bell\'s inequalities by quantum mechanics is proven here. We review actual status of Copenhagen interpretation and notice some other theories, which could replace this interpretation or quantum mechanics itself.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('250', 35, '2000', 'Optické javy v prírode II', 'The Optical Effects in the Nature II', '', 'Article', '1335-4981', '', '46', '51', 'Obzory matematiky, fyziky a informatiky', '', 'The paper deals with the interesting optical effect in the nature formed by the refraction and reflection of light by ice crystals in the atmosphere - halos. The first part of the paper describes some type of ice crystals in the atmosphere they have the shape of hexagonal prisms. The second part analysis how and why to originated halo of 22° and halo of 46°. The final part of the paper treats about sundogs and other type of halos. Keywords: Ice crystals in the atmosphere, halos, origin of halo of 22° and halo of 46°, sundogs and other type of halos.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('251', 35, '2000', 'Úvahy o školskej fyzike', 'The Reflections on the School Physics', '', 'Article', '1335-4981', '', '52', '57', 'Obzory matematiky, fyziky a informatiky', '', 'The results of the analysis of the physical education and the school physics in SR. The topics for the change of curriculum of the physics and for the creation of the school-books of physics.', '');
