INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('254', 36, '1999', 'Nevedia počítať?', NULL, '', 'Article', '1335-4981', '', '17', '22', 'Obzory matematiky, fyziky a informatiky', '', 'As every conscious activity solution of a mathematical problem is also based on previous experience. But it is not always \"mathematical\" experience which influences this problem substantially. This contribution is devoted to the study of this phenomenon. It deals first of all with the cases of deformation of solution process of a mathematical problem on the basis of experience from the \"real\" world for children of age from 7 to 12.
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('255', 36, '1999', 'Variácia na tému 12-ta odmocnina z dvoch', NULL, '', 'Article', '1335-4981', '', '23', '32', 'Obzory matematiky, fyziky a informatiky', '', 'This article deals with various tuning systems of musical instruments with the so called fixed tuning. Problems about tuning concern mathematics, physics, acoustics, psychology, the coding information theory, and musicology.', '');
