INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('292', 17, '2007', 'Dionýz Ilkovič - 100 rokov od narodenia', 'Dionýz Ilkovič – A Centenary of the Birth', '', 'Article', '1335-4981', '', '53', '58', 'Obzory matematiky, fyziky a informatiky', '', 'The article is devoted to the centenary of the birthday of Dionýz Ilkovi? - an outstanding personality of Slovak science and education. The first section provides information about his origin, study and his early jobs in Prague where he reached results in polarography that are acknowledged worldwide. It also describes his activities in Bratislava where he significantly contributed to the development of Slovak universities as well as to the establishment of the Slovak Academy of Sciences. The second section covers his personal profile - his character features and attitudes characteristic for really exceptional personalities.', '');
