INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('349', 10, '2004', '46. ročník Fyzikálnej olympiády', '46th Year of Physics Olympiad', '', 'Article', '1335-4981', '', '52', '53', 'Obzory matematiky, fyziky a informatiky', '', 'The paper is an invitation for students and teachers in the 46th year of the Physics Olympiad. The special attention is devoted to the year 2005, which has been declared as the World year of physics. Several fundamental discoveries made during the 100 years from the start of the theory of relativity and the quantum theories are mentioned in the paper. The emphasis is laid on the sense of physical education for the development of the human personality and the ability to enjoy such nice phenomena like the transition of Venus across the solar disk in June 2004.', '');
