INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('506', 46, '2008', 'Connection of single silicon nanocrystals with carbon nanotubes', 'Connection of Single Silicon Nanocrystals with Carbon Nanotubes', '', 'Article', '1335-4981', '', '29', '32', 'Obzory matematiky, fyziky a informatiky', '', 'The slurry of the article is shown an approach to wire (connect) single nanocrystal with conductive carbon nanotube. Preparation of colonially dispersed nanocrystals offers such unique possibility. Mainly to directly grow carbon nanotube on single silicon nanocrystal (Si-nc) has been realised and it is discussed here in details. In addition, the approach in principle helps localise and manipulate single nanocrystals, and lead to the possible fabrication of new generation of very solid and flexible single Si-nc and carbon nanotubes based hybrid nanodevices.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('507', 46, '2008', 'Palivový článok', 'Fuel Cell', '', 'Article', '1335-4981', '', '33', '40', 'Obzory matematiky, fyziky a informatiky', '', 'In this paper we explain basic principle of fuel cell, types of fuel cells and also where are they used in real life. Renewable sources of energy will be more and more important in future. Fuel cell is one solution for clean source of energy.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('508', 46, '2008', 'Najbezpečnejšia forma komunikácie', 'The Safest Form of Communication', '', 'Article', '1335-4981', '', '41', '50', 'Obzory matematiky, fyziky a informatiky', '', 'Communication is one of the most important human activities. Its original goal was sharing information among people. But sometimes information is intended only for certain persons and it is not acceptable to transfer it using common ways. Therefore people have been developing safe (private) forms of communication for ages.  Absolute privacy of our information had never been guaranteed until scientists showed, during the last decades of the 20th century, that communication without eavesdropping is possible. There exist a number of useful applications of quantum mechanics and quantum cryptography (the name for a part of quantum theory focused on the studying of safe communication) is one of them. In our article we explain the basic principles of quantum cryptography with attention paid to the first known quantum protocol BB84. Theoretical and experimental progress in the field of quantum cryptography during the last few years will be briefly discussed as well.', '');
