INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('639', 56, '2008', 'The Paradox of the Flying Rod', 'The Paradox of the Flying Rod', '', 'Article', '1335-4981', '', '31', '36', 'Obzory matematiky, fyziky a informatiky', '', 'The aim of this article is to propose a simple geometrical method to solve certain kind of two (and higher) dimensional relativistic problems. The method is demonstrated on the well known paradox of the flying rod.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('640', 56, '2008', 'O elementárním modelu GPS systému', 'About the Elementary Model of GPS', '', 'Article', '1335-4981', '', '37', '41', 'Obzory matematiky, fyziky a informatiky', '', 'The article deals with the basic physical principle of GPS. We emphasize the role of relativity of simultaneity here.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('641', 56, '2008', 'Slévání a tuhnutí vody', 'Decantation and Solidification of the Water', '', 'Article', '1335-4981', '', '42', '46', 'Obzory matematiky, fyziky a informatiky', '', 'The aim of this article is to give nontraditional explanation for some properties of water and ice.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('642', 56, '2008', 'Projektové vyučovanie fyziky na ZŠ s využívaním Internetu', 'Project Physics Teaching', '', 'Article', '1335-4981', '', '47', '54', 'Obzory matematiky, fyziky a informatiky', '', 'New information technologies call for the changes of the traditional methods of education. The paper presents the possibilities of changing the present teaching methods of Physics in primary schools via Internet-based project teaching. It introduces the project method used for Physics lessons in the 9th grade in the primary school in Ludanice in teaching the unit of  \"Energy in nature, technology and society\", with related refferences and www sources of physical  applets. The first practical experience is also being discussed.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('643', 56, '2008', 'Texty úloh 1. kola 50. ročníka fyzikálnej  olympiády (šk. r. 2008–2009) kategórie B,C, a D', NULL, '', 'Article', '1335-4981', '', '55', '67', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('644', 56, '2008', '49. Medzinárodná matematická olympiáda', NULL, '', 'Article', '1335-4981', '', '68', '70', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('645', 56, '2008', 'Medzinárodná konferencia Fyzika a etika IV.', NULL, '', 'Article', '1335-4981', '', '71', '0', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('646', 56, '2008', 'Modernizácia a inovácia vyučovania matematickej analýzy (Ján Gunčaga, Jozef Fulier, Petr Eisenmann Katolícka univerzita v Ružomberku, Ružomberok, 2008)', NULL, '', 'Article', '1335-4981', '', '72', '0', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('647', 57, '2009', 'Od pravdepodobnosti ku kombinatorike a nie naopak', 'From Probability to Combinatorics and not Vice Versa', '', 'Article', '1335-4981', '', '1', '12', 'Obzory matematiky, fyziky a informatiky', '', 'Simple explanation of some basic notions of probability theory is presented without using results of combinatorics. On the other hand the problematic of Bernoulli schema leads to calculation of combinatorial numbers.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('648', 57, '2009', 'Integrálne súčty', 'Integral Counts', '', 'Article', '1335-4981', '', '13', '20', 'Obzory matematiky, fyziky a informatiky', '', 'The aim of this paper is to improve teaching of the Riemann integral.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('649', 57, '2009', 'Hry s matematikou, matematika v hrách', 'Games with Mathematics', '', 'Article', '1335-4981', '', '21', '29', 'Obzory matematiky, fyziky a informatiky', '', 'The article deals with playing games in schools. It gives a games situation summary in the world and at our country. Reasons for playing games and especially mathematical skills enlarged by playing games are described en block and on an example of the game Take it Easy!', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('650', 57, '2009', 'Podnetná literatúra pre motiváciu a popularizáciu matematiky', NULL, '', 'Article', '1335-4981', '', '30', '30', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('651', 57, '2009', 'Matematické nástroje - Extremálny princíp', 'Mathematical Tools - Extremal Principle', '', 'Article', '1335-4981', '', '31', '34', 'Obzory matematiky, fyziky a informatiky', '', 'If a set of objects of some mathematical task can be suitable ordered, then it is natural to focus on the least or the greatest object. These special elements can be used as the instrument to solve the task. This mathematical method is illustrated on solutions of various tasks in the paper.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('652', 57, '2009', 'Práca magnetickej sily?', 'Work of Magnetic Force? ', '', 'Article', '1335-4981', '', '35', '41', 'Obzory matematiky, fyziky a informatiky', '', 'An effect of the magnetic force on the current as well as on the electric charge in wire at the electromagnetic induction is analyzed. It is shown that the magnetic force never performs work.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('653', 57, '2009', 'Keplerova úloha - algebraické riešenie', 'Algebraic Solution of the Kepler Problem', '', 'Article', '1335-4981', '', '42', '50', 'Obzory matematiky, fyziky a informatiky', '', 'We present the algebraic solution to the Kepler problem - i.e. we show how to find all the possible trajectories of a testing body in the Newtonian gravitational field of a massive central body - without any need of integrating an equation of motion (differential equation). The presented idea is rather well-known on the scientific level, however, almost absolutely unknown in pedagogical level in spite of the fact it offers a nice possibility to explain the Keplerian elipses to the secondary school students.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('654', 57, '2009', 'Polrok po začiatku reformy', 'Half-year After the School Reform Beginning', '', 'Article', '1335-4981', '', '51', '58', 'Obzory matematiky, fyziky a informatiky', '', 'The changes in the time subsidy and the contents of the school subject physics at secondary grammar schools, which the school reform has brought, enabled that the teachers could apply new reforms and the work methods. There was a seminar held at secondary grammar school of Viliam Pauliny-Tóth in Martin within the Slovak republic, which aimed to exchange the experience about the teaching oh physics in the first year of study. In contribution is included teaching experience within different time subsidies and the division of the school lessons.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('655', 57, '2009', 'Učitelia zo Slovenska už dvakrát navštívili CERN', 'Slovak Teachers Have Already Visited CERN Two Times', '', 'Article', '1335-4981', '', '59', '69', 'Obzory matematiky, fyziky a informatiky', '', 'The article presents a unique event aimed at further education of basic and secondary school physics teachers. During the last two school years slovak teachers participated at one-week workshops in CERN - European Organization for Nuclear Research. They took part at series of lectures concerning particle physics and visited unique research centres and laboratories of CERN. They got known with the up-to date knowledge in the field of particle physics research, technological aspects and applicatons of research in CERN.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('656', 57, '2009', 'Alfonz Haviar sedemdesiatročný', NULL, '', 'Article', '1335-4981', '', '70', '72', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('657', 58, '2009', 'Dvě testové teorie', 'Two Testing Theories', '', 'Article', '1335-4981', '', '1', '10', 'Obzory matematiky, fyziky a informatiky', '', 'We have two basic models for statistical data processing of the test results: item response theory (IRT) and the classic theory of tests (CTT). All of this models give the possibilities of analyze and therefore different data interpretation.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('658', 58, '2009', 'Matematické nástroje', 'Mathematical Tools – Semi-Invariants', '', 'Article', '1335-4981', '', '11', '15', 'Obzory matematiky, fyziky a informatiky', '', 'A semi-invariant is the quantity which is changed monotonically and gains only finite values. Semi-invariants are often used in the analysis of evolving systems to show that certain final configurations must occur. Every investigated object of a problem is assigned some value of quantity and is defined a suitable operation on the set of objects. We concentrate on the least\"or the greatest value of semi-invariant and we the problem solve by its means.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('659', 58, '2009', 'Gustave Choquet matematik s intuíciou básnika', NULL, '', 'Article', '1335-4981', '', '16, 22, 34', '0', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('660', 58, '2009', 'Je treba pestovať súťaže pre talenty?', 'How to Develop Contests for Talents?', '', 'Article', '1335-4981', '', '17', '21', 'Obzory matematiky, fyziky a informatiky', '', 'The sense of Mathematical Olympiad and some problems connected with this competition in Slovakia are pointed out from several points of view in the article.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('661', 58, '2009', 'Texty úloh domáceho kola 59. ročníka matematickej olympiády', NULL, '', 'Article', '1335-4981', '', '23', '34', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('662', 58, '2009', 'Not Everything is Linear or Quadratic - Two Physics Problems of Mechanics', 'Not Everything is Linear or Quadratic – Two Physics Problems of Mechanics', '', 'Article', '1335-4981', '', '35', '41', 'Obzory matematiky, fyziky a informatiky', '', 'Secondary school students can have an inccorect idea that all quantity dependences in physics are linear or quadratic. In this paper, we present proposals of two physics problems in Mechanics which could challenge these wrong ideas. These problems can be implemented into common lessons of physics at grammar school level.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('663', 58, '2009', 'Aplikácia digitálnej techniky vo vlnovej optike', 'Digital Technique Application in a Wave Optics', '', 'Article', '1335-4981', '', '42', '46', 'Obzory matematiky, fyziky a informatiky', '', 'The article deals with a design of the wave optics experiment. It contains complete description of the experiment, which can by used either as a laboratory work, or as a demonstration experiment at secondary school physics lessons.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('664', 58, '2009', 'Primárne energetické zdroje a efektívnosť varenia', 'Primary Energy Sources and Effectivity of Cooking', '', 'Article', '1335-4981', '', '47', '59', 'Obzory matematiky, fyziky a informatiky', '', 'The on-going reform of education requires students and teachers to develop the key competencies. This article shows one of the possible activities aimed at developing competencies in solving problems related to energy. Energy prices are increasing what stresses the question, how to maximize savings. The statement, that the cheapest energy is the one saved, is still true, because it needn\'t be produced, transported, transformed, mined, imported and processed. In this paper, the closer look at the primary energy resources and energy saving options for cooking in the household is taken. We deal with the efficiency of cooking. Efficiency of heat transferred to the water in a pot is found out experimentally, depending on the material from which the pot was made, on the area of pot\'s bottom. The result of experiment depends also on the fact whether the cooker has been covered. We compare the efficiency of three appliances: gas cooker, electric cooker and electric kettle.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('665', 58, '2009', 'Experimenty počas cesty do CERN-u', 'Experiments During the Journey to CERN', '', 'Article', '1335-4981', '', '60', '67', 'Obzory matematiky, fyziky a informatiky', '', 'There is a series of physical experiments realized by physics teachers - national teachers program participants on the way to CERN and in CERN presented. Experiments concern measurements of air temperature, altitude, atmospheric pressure, boiling point of water, dose equivalent of radiation and UV index.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('666', 58, '2009', 'Texty úloh 51. ročníka fyzikálnej olympiády (šk. r. 2009-2010) kategórie E, F a G', NULL, '', 'Article', '1335-4981', '', '68', '72', 'Obzory matematiky, fyziky a informatiky', '', '', '');
