INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('669', 59, '2009', 'James Sylvester - matematik hrdý na svoju poéziu', NULL, '', 'Article', '1335-4981', '', '3', '4', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('670', 59, '2009', 'Čo s Riemannovým integrálom', 'What to do with Riemann´s Integral', '', 'Article', '1335-4981', '', '5', '17', 'Obzory matematiky, fyziky a informatiky', '', 'A very simple integration method for integration of continuous functions on one-dimensional compact interval is reminded. It is based on the known Riemann construction.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('671', 59, '2009', 'Mikuláš Kuzánsky - priateľ protikladov', NULL, '', 'Article', '1335-4981', '', '17', '18,24', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('672', 59, '2009', 'Dĺžka slova', 'The Length of Word', '', 'Article', '1335-4981', '', '19', '23', 'Obzory matematiky, fyziky a informatiky', '', 'The article deals with application of probability theory in literary text analysis from word length aspect, specifically in poems by Rudolf Dilong.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('673', 59, '2009', 'Matematické nástroje - Aritmetický a geometrický priemer', 'Mathematical Tools – Arithmetic and Geometric Mean', '', 'Article', '1335-4981', '', '25', '31', 'Obzory matematiky, fyziky a informatiky', '', 'The relation of arithmetic and geometric mean is used often in mathematics. The use of this mathematical tool is illustrated on solutions of various tasks in the paper.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('674', 59, '2009', 'Spomíname: 50 rokov Fyzikálnej olympiády v Česko - Slovensku', NULL, '', 'Article', '1335-4981', '', '32,47,66', '0', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('675', 59, '2009', 'Study of the efficacy of MBL activities in physics teaching in Slovakia', 'Study of the Efficacy of MBL Activities in Physics Teaching in Slovakia', '', 'Article', '1335-4981', '', '33', '41', 'Obzory matematiky, fyziky a informatiky', '', 'The contribution deals with the use of MBL activities in physics teaching in Slovakia. Teachers usually do not have the technological background and capacity to transform traditional lab activities into computer-based lab activities. Therefore we realized a project named Labworks in MBL. The aim of the project was to design computer-based lab activities for grammar school curriculum (students aged 16-17), prepare worksheets for active learning in MBL, gain experience in the field of pedagogical methods, role of the teacher in the class, instructional materials, etc., educate physics teachers for teaching in MBL and test the effectiveness of teaching in MBL. The paper discusses experiences, results of research regarding the effectiveness of teaching with MBL, and makes recommendations regarding the pedagogical methods used.
