INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('677', 59, '2009', 'Bartovo odvodenie termodynamickej bilančnej rovnice energie', 'Derivation of the Thermodynamic Equation of the Energy with Barta', '', 'Article', '1335-4981', '', '43', '47', 'Obzory matematiky, fyziky a informatiky', '', 'The connection between thermodynamic energy, warm quantity and work is derived, using the fluctuations of forces and displacements of microscopic parts of vessel walls, generated by the molecules impacts. By this way is also the warm quantity defined.', '');
