INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('681', 60, '2009', 'Prípadová štúdia posudzovania úrovne vyučovania informatiky a programovania z hľadiska vybraných faktorov', 'Case Study of Teaching Informatics and Programming Level Assessment from the Position', '', 'Article', '1335-4981', '', '31', '40', 'Obzory matematiky, fyziky a informatiky', '', 'The authors present a part of their research results, they obtained within a wider research focused on possibilities to influence students’ attitudes to individual subjects. Following the empirically derived hierarchy of subjects identifying the degree of popularity of the subjects and influence of various motivation factors on students’ attitudes to the subjects the authors discuss students’ interest in study informatics and programming and try to identify the reasons of students’ interest or disinterest in these subjects.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('682', 60, '2009', 'Fyzikálne vzdelanie moderného človeka', 'Physical Knowledge of Modern Society', '', 'Article', '1335-4981', '', '41', '50', 'Obzory matematiky, fyziky a informatiky', '', 'National and global projects the development of which was oriented to the education, sciences and technical innovation programmes started to increase at the turn of the 2nd and the 3rd millennium. New terms, like e.g. the “Educational Society” or the “Knowledge Economy”, were created. They should contribute for the increase of the dynamic growth of the individual countries economy. The project “Lisbon Declaration” was accepted with optimism in the European Union (EU) and involved in the national programmes of different European countries. The developmental programme of the knowledge economy in Slovakia was given the title “Minerva”. Even though the goals of the EU programme as well as the individual countries weren’t real, and the “revised” programmes were adjusted and accepted after 2007, it can be said that the base of these programmes, a high quality educational system for children, young and adults, remains correct. The authors researched the opinions of high school students on physics teaching and the role of this subject in the educational system of the high school.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('683', 60, '2009', 'O jednom tvrdení, ktoré sa traduje v našich učebniciach', 'About One Statement that is being Used in our Textbooks', '', 'Article', '1335-4981', '', '51', '54', 'Obzory matematiky, fyziky a informatiky', '', 'This article focuses on how we are limited by traditional patterns when expressing the motion of a mathematical, physical pendulum.', '');
