INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('695', 61, '2010', 'Globálny problém ochrany ovzdušia z hľadiska   skleníkového plynu', 'Global Problem of Air Protection from the Aspect of Greenhouse Gas', '', 'Article', '1335-4981', '', '23', '36', 'Obzory matematiky, fyziky a informatiky', '', 'In this article we would like to verify that the productions of cement, lime and lime products have significance. Without cement the building come to a stop. Without lime and limestone we do not imagine our life, because with them „slacking\" side- and wrong-effect of oxide of nitrogen and sulfur. It was proven, that lime and lime products decontaminate. We proved also, that lime and cement water solution set backwards greenhouse gas, but no in every final product. Inside of them we are always producing greenhouse gases (C02), already we produce less carbon-dioxide than in energetics. Can we defend that inventions and industrial revolution will not be appreciated in negative sense? Shall we say, how cement and lime producers contaminate the total environment, but in small numbers speak juice bonding is C02 bearing. Are the arrangements of cement and lime producers sufficiently effective for minimalization of the influence of carbon dioxide? The aim of building materials producers is to reduce more and more negative obtain a result for the living environment. In the international conference- Kyoto the states make a compromise, that prescribe the reducing of C02.', '');
