INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('705', 62, '2010', 'The Position of Interactive Models among Visual Aids', 'The Position of Interactive Models among Visual Aids', '', 'Article', '1335-4981', '', '35', '40', 'Obzory matematiky, fyziky a informatiky', '', 'In this contribution we deal with the interactive models specialized on physics, mainly from the point of view of effectivity and popularity according to their position among other visual aids. To establish the position of interactive models among selected visual aids we use the revised Thurstone\'s method of paired comparisons in groups of teachers and high school students.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('706', 62, '2010', 'Formulácie Gaussovej vety pre vákuum a dielektrikum', 'Formulation of the Gauss´Law for the Vacuum and Dielectric', '', 'Article', '1335-4981', '', '41', '43', 'Obzory matematiky, fyziky a informatiky', '', 'Detailed explanation of the Gauss\'s law is given here. Although microscopically, all eleectic charge is fundamentally the same, there are often practical reasons for wanting to treat bound charge differently from free charge in dielectric materials.', '');
