INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('708', 62, '2010', 'Aplety vo vyučovaní fyziky', 'Applets in Physics Teaching', '', 'Article', '1335-4981', '', '45', '50', 'Obzory matematiky, fyziky a informatiky', '', 'Development of ICT and computer rooms building in schools enable to make use of different computer applications in teaching including applets. In this note we present few physical applets satisfying conditions for their applicability in teaching. We describe their structure and present the possibility of their use on suitable chosen examples', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('709', 62, '2010', 'K historii cesty od elektrodynamiky ke speciální teorii relativity', 'The History of the Journey from Electrodynamics to Special Theory of Relativity', '', 'Article', '1335-4981', '', '51', '67', 'Obzory matematiky, fyziky a informatiky', '', 'The introduction emphasizes an importance of experimental pillars of electromagnetism (about an interaction, a source of the magnetic field, an electromagnetic induction). Weber\'s experimental observation of 1852 about a relationship among permittivity, permeability and the light velocity c is identified as a bridge between electrodynamics and that time unknown special relativity. The importance of introducing of a displacement current by Maxwell who brought it to the wave equation and a development of electromagnetic theory of light is pointed out. Heaviside\'s description of the electromagnetic field of high-speed electric charges is valued. It deals with a measurement (verification) of the second-order magnetic field of high-speed electrons, the contribution made by the author. Einstein\'s special relativity is a way out of aberrant ether\'s hypotheses. The conclusion outlines didactically an appropriate interpretation of electrodynamics which is based on the special relativity and Coulomb\'s law.', '');
