INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('719', 63, '2010', 'Jedna problémová úloha pre vašich žiakov a jedna aj pre vás. One problem - Solving Task for Your Students and One also for You', 'One Problem – Solving Task for Your Students and One for You', '', 'Article', '1335-4981', '', '39', '40', 'Obzory matematiky, fyziky a informatiky', '', 'The problem of swimming magnetic needle and coil with corresponding magnetic poles on its opposite ends.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('720', 63, '2010', 'Lagrangeove body v gravitačnom poli dvoch telies', 'Lagrangian Points in the Gravitational Field of Two Bodies', '', 'Article', '1335-4981', '', '41', '51', 'Obzory matematiky, fyziky a informatiky', '', 'One of the main problems of celestial mechanics is how to determine the motions of three bodies caused by exertion of the forces of the mutual gravitational attraction. Under the influence of the gravitational forces, individual bodies orbit around a mutual centre of gravity. When analyzing their motions, it is necessary to determine the positions and velocities of the bodies at any moment in the past or future. When three bodies are concerned, this is impossible to solve completely. J. L. Lagrange proved that in special cases there is a completely analytical solution to the motions of three bodies when the third body is positioned in one of the five libration points in relation to the first two bodies. Those positions are called Lagrangian points. In this paper, I have shown the derivation of the position of those points.', '');
