INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('737', 65, '2011', 'Koncepčné a metodické východiská hodnotenia stavu vyučovania informatiky na vyššom sekundárnom stupni vzdelávania  v Slovenskej republike', 'Conceptual and Methodical Starting Points of Informatics Teaching Evaluation on the Higher Secondary Stage of Education in the Slovak Republic', '', 'Article', '1335-4981', '', '25', '32', 'Obzory matematiky, fyziky a informatiky', '', 'The contribution is based on a widely conceived international research oriented on a comparative evaluation of contemporary state of Informatics teaching  from the point of view of specific factors at the higher secondary level of education in the Slovak and Czech Republic. The author concentrates on the specification of the factors that significantly influence quality of teaching Informatics from the students´ point of view and presents an analysis of the questionnaire reliability used to create a first-rate quality tool for obtaining reliable data in the frame of the above-mentioned international research.', '');
