INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('739', 65, '2011', '„Process Information“ in the New Leaving Examination in Physics in the Czech Republic', '“Process Information“ in the New Leaving Examination in Physics in the Czech Republic', '', 'Article', '1335-4981', '', '39', '45', 'Obzory matematiky, fyziky a informatiky', '', 'One of the objectives of the new leaving examination in physics (at upper secondary schools in the Czech Republic) is to prove how students can „process information“. In this paper, we present six different physics problems that could help students to develop this skill.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('740', 65, '2011', 'Celoštátne kolo fyzikálnej olympiády 7. – 10. apríl 2011 Stredná záhradnícka škola Piešťany (Red.)', NULL, '', 'Article', '1335-4981', '', '46', '0', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('741', 65, '2011', 'Hvezdáreň a planetárium ako súčasť vyučovania  astronómie', 'Observatory and Planetarium as the Part of Astronomy Education', '', 'Article', '1335-4981', '', '47', '56', 'Obzory matematiky, fyziky a informatiky', '', 'Observatories and planetariums as specialized cultural-educated institutions apply themselves to astronomy and similar science discipline\'s popularization. Their activity is for pupils, students and educators of all level of school, preprimary children, various interest groups and also individuals from general public. In observatories, planetariums there are proposed for general public interesting, even unconventional views on the Universe, astral sky, Earth and human place in the Universe, by the form of multimedia programs, presentations, video projections, evening at telescope, expositions etc. The article deals with the task and position of observatories and planetariums in the education not only Physic and Astronomy, but also other, mainly Science subjects.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('742', 65, '2011', 'Reálný experiment ve výuce fyziky a v soutěži  Fyzikální olympiáda', 'The Real Experiment in Physics Teaching and Competition of Physics Olympiad', '', 'Article', '1335-4981', '', '57', '72', 'Obzory matematiky, fyziky a informatiky', '', 'The contribution in the introductory part \"Physics and experiment\" deals with the significance of experiment in building the physics as the science of the real world. The second part focuses on real experiments in physics education, which should be built on the fundamental experiments. Real experiments in physics education have a triple meaning: cognitive, motivational and contributing significantly to the development of fine motorics (in the laboratory exercises). The third part of the contribution is devoted to an experimental problem in the Physics Olympiad. Here you can observe the opposite trend than in the general teaching of physics - Experimental role playing an increasingly important role in the competition. We see this especially in the International Physics Olympiad, which is often a difficult experimental problem, whose solution requires skills in addition to the required dose of invention. The article gives 21 examples of advanced experimental tasks for the International Physics Olympiad. At the end is summarized the importance of experiment as the science subject and the subject of teaching.', '');
