INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('747', 66, '2011', '1st Slovak Natural Sciences e-Laboratory', '1st Slovak Natural Sciences e-Laboratory', '', 'Article', '1335-4981', '', '31', '37', 'Obzory matematiky, fyziky a informatiky', '', 'The paper presents the 1st Slovak e-laboratory of nature sciences with real remote experiments and the data transfer. The laboratory uses a unified approach, as the hardware used is the ISES (Internet School Experimental System) and its modules, while the software for the server-client connection is based on internet pages and Java applets. E-laboratory is free available on the page http://kf.truni.sk/remotelab and in the present time it consists of five experiments from physics: Environmental monitoring, Simple pendulum, Free fall, Faraday’s law, Energy transfer in oscillators, and the first e-experiment from chemistry, Electrochemical cell.    ', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('748', 66, '2011', '5. ročník Play Energy 2011 „Objavme energiu“', NULL, '', 'Article', '1335-4981', '', '0', '0', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('749', 66, '2011', 'Vplyv informačných a komunikačných  technológií na zvyšovanie záujmu žiakov o fyziku', 'Influence of the Information and the Communication Technologies on the Increase of Pupil´s Interest in the Physics', '', 'Article', '1335-4981', '', '39', '46', 'Obzory matematiky, fyziky a informatiky', '', 'Content of  this article represents the final paper in the national project Modernization of education at secondary grammar schools. The aim of the final paper is to verify the influence of information and communication technologies on the increase of students‘ interest in choosing physics as voluntary and graduation subject. The article contains quantitative state analysis of choosing physics as voluntary and graduation subject by students of secondary grammar school in Košice, Šrob{\'a}rova 1, in the academic years of 2006/2007 to 2010/2011. It formulates hypotheses of pedagogic research as well as describes pedagogic experiment and results of the research. The role of pedagogic experiment and research was to change the current status and increase the interest in choosing physics as voluntary subject in the academic year 2011/2010 and graduation subject in the academic year 2012/2013. The article may serve as guidelines for other teachers in order to influence students’ behaviour because the problem of low interest of students in physics is rarely mentioned in expert lterature.', '');
