INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('760', 67, '2011', 'Žiacky experiment: voda vytekajúca z nádoby', 'The Schoolchild Experiment: Water Flowing out of Container', '', 'Article', '1335-4981', '', '21', '30', 'Obzory matematiky, fyziky a informatiky', '', 'In this article we introduce an individual pupil’s experiment. Theme of this experiment is the flow of water through a hole in the bottom of the container. The aim of the activity is to develop pupil’s competence of scientific work – to state the hypotheses, planning of experiments, select tools... We introduce results of our measurements, which may be useful for teachers. First, we solve the problem, how the volume of water in the tank depends on the time, which is needed for outflow of water from the tank through the hole at the bottom. Problem is solved theoretically first and then it is verified by the measurement. We describe then the measurement of time needed to empty the tank as a function of straw length. We suggest possible variation of the problem, which can be considered as a simple experiment realizable in a few minutes.', '');
