INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('777', 68, '2011', 'Kondenzátor s dielektrikom', 'Capacitor with a Dielectric Slab', '', 'Article', '1335-4981', '', '35', '40', 'Obzory matematiky, fyziky a informatiky', '', 'A contribution deals with a parallel-plate capacitor with a dielectric slab between plates. The slab can move without friction. Two cases are considered: 1) A charged capacitor with the slab is closed system, where a law of conservation of energy is valid. Here is an electric charge Q = const.. 2) The capacitor is connected to a battery, the system is open, and a voltage U = const.. A role of the fringing field around the ends of the capacitor as well as role of the charges in the corners inside the capacitor is explained.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('778', 68, '2011', 'Úvaha o odstredivej sile', 'Some Considerations about the Centrifugal Force', '', 'Article', '1335-4981', '', '41', '46', 'Obzory matematiky, fyziky a informatiky', '', 'Using of a centrifugal force is connected with a lot of inaccuracies and mistakes. It is very deceitful concept because correct quantitative result can be obtained in spite of physically incorrect solution. That´s why such physically incorrect usage of centrifugal force can be found even in many textbooks and workbooks. We will try to clarify the using this force. Correct solutions will be demonstrated.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('779', 68, '2011', 'Školský vzdelávací program Fyzika a experiment', 'The School Education Program: Physics and Experiment (Experiences from the Grammar School of Viliam Pauliny-Tóth in Martin)', '', 'Article', '1335-4981', '', '47', '60', 'Obzory matematiky, fyziky a informatiky', '', 'The school education program of the subject Physics at the Secondary grammar of Viliam Pauliny-Tóth is focused mainly on the development of mathematical-scientific, information, educational and social-personal competencies as well as on the competencies of the solving problems by the experimental activities of the students. There are also described the development of the school education program, the experiences from its use, and some examples of lesson plans, study materials as well as the instructions for the experimental work of the students.', '');
