INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('784', 69, '2012', 'Development of the Operations of Cognitive Processes  with Dynamic Geometric Software', 'Development of the Operations of Cognitive Processes with Dynamic Geometric Software', '', 'Article', '1335-4981', '', '3', '16', 'Obzory matematiky, fyziky a informatiky', '', 'A mathematical notion, problem or algorithm should not be taught for its own sake, art for art. Thus the most important task of a Mathematics teacher is to develop the students’ way of thinking through acquiring certain frames of knowledge. All cognitive operations are essential for both understanding and problem solving. It is substantial that students should solve such exercises or types of exercises that involve several cognitive operations. Furthermore, it is important to create a motivational base. In this, interactivity provided by the use of ICT tools may play an important role. GeoGebra can provide facilities in creating these requirements. Supported with relevant research data, I would like to speak about my experiences of this matter, and I would also like to illustrate through some example programs how we can use GeoGebra in developing cognitive operations.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('785', 69, '2012', 'Obsahovo a jazykovo integrované vyučovanie -  matematika v slovenskom jazyku na slovenskej národnostnej škole v Maďarsku', 'Content and Language Integrated Learning – Mathematics in Slovak Language at the Slovak Nationality School in Hungary', '', 'Article', '1335-4981', '', '17', '22', 'Obzory matematiky, fyziky a informatiky', '', 'Content and Language Integrated Learning (CLIL) can support the using of minority language in different subjects. In our chapter we present this method in the case of school mathematics. There is not analysed the possibilities of this method in Hungarian minority schools up this time. The first implementation must be in the preparing of future Slovak minority teachers.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('786', 69, '2012', 'O zovšeobecneniach fuzzy množín', 'On Generalisation of Fuzzy Sets', '', 'Article', '1335-4981', '', '23', '37', 'Obzory matematiky, fyziky a informatiky', '', 'We focus on various kinds of generalizations of (ordinary) fuzzy sets. In our opinion, the most important ones are: intuitionistic fuzzy sets, interval-valued fuzzy sets and type-2 fuzzy sets. We discuss each of them, and put emphasis on motivation for such a generalization. So the main aim is not to bring new results, the paper only summarizes known facts concerning generalizations of fuzzy sets. Moreover, the intersection, union, complement and inclusion for ordinary / intuitionistic / interval-valued / type-2 fuzzy
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('787', 69, '2012', 'Informácie o matematických konferenciách', 'Information about Mathematics Conferences', '', 'Article', '1335-4981', '', '38', '38', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('788', 69, '2012', 'Rekviem nad spinovým echom', 'Requiem for a Spin Echo', '', 'Article', '1335-4981', '', '39', '45', 'Obzory matematiky, fyziky a informatiky', '', 'At present the diagnostic method  NMR (Nuclear Magnetic Resonance) is very popular and useful, mainly in medicine. It is based on the principle of free (Lamor) precession or free induction called FID (Free Induction Decay).  Free precession was used in the method called “spin  echo” which was known many years before the tomographs were constructed in their current form. In principle the method “spin echo” uses radiation of a sample (organic material) by pulses of high frequency electromagnetic radiation (pulse NMR) and measures relaxation time of protons present in the test sample. Relaxation times are typical processes for the exchange of energy between the sample and its environment. The author of this article used this method and carried out the measurements with his colleagues from the Faculty of Sciences, Comenius University in Bratislava, already in 1960s. In the paper the author describes some basic experiments carried out by means of  “spin echo” method and he also presents their interpretation.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('789', 69, '2012', 'Informácie o fyzikálnych konferenciách', 'Information about Physics Conferences', '', 'Article', '1335-4981', '', '46', '46', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('790', 69, '2012', 'O fyzice, jejím významu  a spoločenskom postavení', 'On Physics, its Significance and Position in the Society', '', 'Article', '1335-4981', '', '47', '60', 'Obzory matematiky, fyziky a informatiky', '', 'A position of the physics in a society is discussed – both in the historical and present-day contexts. First it focuses on the physics as a fundamental science ex-ploring the most general rules of natural phenomena and mentions the methods used for this examination. In the next part it emphasizes a role of the physics in the other natural sciences, especially in chemistry, biology and contemporary medicine. The importance of the physics for technical branches is pointed out. In conclusion the physics as an educational subject is treated.', '');
