INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('804', 70, '2012', 'The Cassini-Huygens Mission (1st Part)', 'The Cassini-Huygens Mission (1st Part)', '', 'Article', '1335-4981', '', '31', '40', 'Obzory matematiky, fyziky a informatiky', '', 'The goal of the Cassini-Hyugens Mission has been to send an orbiter to Saturn and a lander to Titan, Saturn’s largest moon. The orbiter-lander tandem (Cassini Orbiter with the Huygens Probe) was launched in October 1997, it arrived at Saturn in July 2004. The Probe landed on Titan in January 2005. The Orbiter continues circling Saturn, all systems performing flauwlessly. Cassini radar discovered lakes of liquid hydrocarbons on Titan. Cassini cameras imaged volcanic eruption on Enceladus. Titan is the second body in the Solar System with free liquids on its surface. Enceladus is the fourth body (after Earth, Io, and Triton) exhibiting volcanic activity. Operations of the Cassini Orbiter have been extended through the year 2017.', '');
