INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('809', 70, '2012', 'Termíny čas a doba nie sú synonymá', 'The terms and Duration are not Synonymous', '', 'Article', '1335-4981', '', '69', '72', 'Obzory matematiky, fyziky a informatiky', '', 'The ambiguity of the term time in the physical textbooks is commented. It serves as a name for the point on the time axes, as well as for the time interval. Some examples are presented, which can lead to misunderstanding. The legalization of the short equivalent for the time interval in Slovak language is presented by the citations of some sources. The legalization of this short synonyma is supported also by the Ludovit Stur Institute of Linguistics Slovak Academy of Sciences.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('810', 71, '2012', 'Vedecké pozadie jednej úlohy matematickej olympiády a širšie súvislosti', 'Scientific Background and Broader Context of a Selected Problem in the Mathematical Olympiad', '', 'Article', '1335-4981', '', '1', '8', 'Obzory matematiky, fyziky a informatiky', '', 'The scientific background and broader connections of one contest problem from Mathematical Olympiad from the area of combinatorial geometry are in this paper. Many open questions are formulated, too. Solution of these requires maybe elementary methods only, but the answer is certainly publishable – perhaps in the most prestigious journals.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('811', 71, '2012', 'Outstanding mathematicians in the 20th century: Jenő Egerváry (1891–1958) establisher of the Hungarian method', 'Outstanding mathematicians in the 20th century: Jenő Egerváry (1891-1958), establisher of the Hungarian Method', '', 'Article', '1335-4981', '', '9', '18', 'Obzory matematiky, fyziky a informatiky', '', 'Jenő Egerváry was an outstanding Hungarian mathematician. He was born
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('812', 71, '2012', 'Modelovanie a jeho geometrické aplikácie vo vyučovaní matematiky a informatiky', 'Modelling and Its Geometric Application in Teaching Mathematics and Informatics', '', 'Article', '1335-4981', '', '19', '26', 'Obzory matematiky, fyziky a informatiky', '', 'In a contribution we are proposing example of teaching of basics of modeling
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('813', 71, '2012', 'The Cassini-Huygens Mission (continued from previous issue)', 'The Cassini-Huygens Mission (continued from previous issue)', '', 'Article', '1335-4981', '', '27', '40', 'Obzory matematiky, fyziky a informatiky', '', 'The goal of the Cassini-Hyugens Mission has been to send an orbiter to Saturn and a lander to Titan, Saturn’s largest moon. The orbiter-lander tandem (Cassini Orbiter with the Huygens Probe) was launched in October 1997, it arrived at Saturn in July 2004. The Probe landed on Titan in January 2005. The Orbiter continues  circling Saturn, all systems performing flauwlessly. Cassini radar discovered lakes of liquid hydrocarbons on Titan. Cassini cameras imaged volcanic eruption on Enceladus. Titan is the second body in the Solar System with free liquids on its surface. Enceladus is the fourth body (after Earth, Io, and Triton) exhibiting volcanic activity. Operations of the Cassini Orbiter have been extended through the year 2017.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('814', 71, '2012', 'Školská fyzika – její poslání, problémy a východiska (1. časť)', 'School Physics – Its Role, Problems and Solutions (Part 1)', '', 'Article', '1335-4981', '', '41', '50', 'Obzory matematiky, fyziky a informatiky', '', 'It deals with a transfer of physics as a fundamental science in physics tuition at schools of various levels and orientation. It emphasizes a role of school physics and presents problems appeared in the current tuition. It compares a physics development as a science in the context with the contents of teaching subject matter in Physics and provides an overview of physics textbooks. The contemporary school physics (especially at the grammar school level) is not able to explain basically significant results of the present-day school physics due to their mathematical difficulty. The article indicates specific solutions to this problem that can lead to increasing interest of children and youth not only in physics but in other natural sciences and technical subjects as well.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('815', 71, '2012', 'Texty úloh 54. ročníka fyzikálnej olympiády (šk. r. 2012 - 2013) kategórie A, B (B1-4)', 'Tasks of the First Cycle of the 54th Physics Olympiad (School Year 2012 - 2013) Categories A,B', '', 'Article', '1335-4981', '', '51', '60', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('816', 71, '2012', '18. konferencia DIDFYZ ´12, Fyzikálne vzdelávanie v systéme reformovaného školstva', '18th Conference DIDFYZ´12: Physics Education in the System of School Reform', '', 'Article', '1335-4981', '', '60, 72', '0', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('817', 71, '2012', 'Návšteva nositeľa Nobelovej ceny za fyziku  Douglasa Deana Osheroffa na Slovensku', 'The Visit of Professor Douglas Dean Osheroff, a Nobel Laureate in Physics, to Slovakia.', '', 'Article', '1335-4981', '', '61', '64', 'Obzory matematiky, fyziky a informatiky', '', 'A Nobel Laureate in Physics in 1996, Douglas Osheroff (Standford University in California) visited Slovakia from 24-29 June 2012. Professor Osheroff met with students from secondary schools, as well as with the researchers and teachers of the universities in Bratislava. His discussion with students (“An Hour of Questions and Responses”) took place at the Slovak University of Technology in Bratislava. Professor’s speech addressed to academicians dealt with “The Discovery of Superfluidity in Helium 3”.  In the following days, Professor Osheroff with his wife visited the nuclear plant in Mochovce and the region of High Tatras. The visit to Slovakia was of special significance, since Professor Osheroff’s grandmother came from Slovakia.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('818', 71, '2012', 'JSMF a rozvoj matematiky a fyziky na Slovensku (konferencia pri príležitosti 150. výročia založenia spoločnosti matematikov a fyzikov)', 'The Union of Slovak Mathematicians and Physicists and the Development of Mathematics and Physics in Slovakia (Conference Dedicated to the  150th Anniversary of the Union)', '', 'Article', '1335-4981', '', '65', '68', 'Obzory matematiky, fyziky a informatiky', '', '\"Spolok pro volné přednášky z mathematiky a fysiky\" [The Association for Free Lectures on Mathematics and Physics], the first association of mathematicians and physicists in Bohemian and Slovak region, was established in 1862 at the Faculty of Arts of the K.K. Charles Ferdinand in Prague.  To commemorate the 150th anniversary of the event, The Union of Slovak Mathematicians and Physicists organized a special conference. On this occasion, thirty scientists and teachers received awards from the Minister of Education and sixty-two mathematicians and physicists were given Commemorative Letters of The Scientific Society of Mathematicians and Physicists.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('819', 71, '2012', 'Odišiel matematik a kňaz RNDr. Vladimír Jukl', 'RNDr. Vladimír Jukl, a Mathematician and Priest has died ', '', 'Article', '1335-4981', '', '69', '71', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('820', 72, '2012', 'Poznámka o istom neurčitom integrále', 'A Note on an Antiderivative Integral', '', 'Article', '1335-4981', '', '1', '4', 'Obzory matematiky, fyziky a informatiky', '', 'This paper is devoted to interpretation of an antiderivative of y = 1/x. An application of it to solving one ordinary differential equation is presented.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('821', 72, '2012', 'O Eulerových substitúciách geometricky', 'On Euler´s Substitutions Geometrically', '', 'Article', '1335-4981', '', '5', '14', 'Obzory matematiky, fyziky a informatiky', '', 'In the article we deal with Euler’s substitutions as general techniques of integration of irrational functions. Although for finding the indefinite integral of these functions it is sufficient to know their form we go deeper in the understanding of the substitutions and try to interpret their geometrical character. Base on that we derive their form.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('822', 72, '2012', 'O Sichermanových kostkách  a jejich zobecnění', 'On the Subject of the Sicherman Dice  and Its Generalisation', '', 'Article', '1335-4981', '', '15', '20', 'Obzory matematiky, fyziky a informatiky', '', 'Many different types of games involve the use of numbered dice. The most common type of die used is the standard six-sided die with the numbers one through six used on its six sides. What if there was another way of numbering a set of dice (using only positive integers) that would create the same probability outcomes as those of a standard set of dice?', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('823', 72, '2012', 'Simulácia  náhodných udalostí vo vyučovaní pravdepodobnosti a štatistiky', 'Simulation of Random Events in Teaching Probability and Statistics', '', 'Article', '1335-4981', '', '21', '35', 'Obzory matematiky, fyziky a informatiky', '', 'Modern digital technologies can be appropriately applied in the teaching of probability and statistics. Computer simulations represent an important part of application of digital technologies and they can be used to demonstrate various probability phenomena and patterns, analysis and evaluation of results of random experiments. Well-processed data in the form of summary tables and graphs can help in testing of students’ hypotheses or in guiding their considerations and decisions. In the article we
