INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('833', 74, '2013', 'Množiny bodov rovnako vzdialených od dvoch útvarov', 'Sets of Points with the Same Distance from Two Objects', '', 'Article', '1335-4981', '', '1', '10', 'Obzory matematiky, fyziky a informatiky', '', 'In this paper we deal with the problem of tracing the set of points having the same distance from two objects. The studied objects are classical Eucliedean geometry shapes – point, line and circle. The problem can be considered as a degenerate case of the Problem of Apollonius. The paper is written as a gradual discovery, it can be used in school in a math group.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('834', 74, '2013', 'Využitie programovacieho jazyka Imagine vo vizualizácii algoritmov', 'The Use of the Programming Language Imagine for Algorithm Visualisation', '', 'Article', '1335-4981', '', '11', '17', 'Obzory matematiky, fyziky a informatiky', '', 'In the application of the principle of the synoptically play important role visualization and the creation and application of models to demonstrate and study the various objects and phenomena of the real world. Using the tools for visualization and modeling we are developing visual cognition student creative and logical thinking. The artist in the article dealing with the programming language Imagine and its options for the creation of various educational software suitable for visualizing.', '');
