INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('836', 74, '2013', 'Zaujímavý integrál', 'Interesting Integral', '', 'Article', '1335-4981', '', '19', '26', 'Obzory matematiky, fyziky a informatiky', '', 'The paper presents a definite integral, which most of the mathematical softwares that we tried, were not able to compute. Using a substitution or a symmetry of the integrated function, we can compute it “by hand”. However, a computer can be utilized when looking for a suitable strategy of computation.', '');
