INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('843', 75, '2013', 'Ako sprístupniť pojem tenzora', 'How to Make the Concept of Tensor', '', 'Article', '1335-4981', '', '43', '50', 'Obzory matematiky, fyziky a informatiky', '', 'A simple model of two dimensional electrically anisotropic sample is used to explain the content of the term tensor and its usefulness. In anisotropic solids the vector of current density doesn´t need to be parallel to the electric field intensity vector. Therefore the relation between these vectors is not a simple scalar multiplication, but an algebraically more complicated relation is needed, mediated by tensor. In the article the connection between matrix and tensor formulation is mentioned, the tensor form in three dimensional cartesian coordinate system and for illustration the tensor characterizing optical properties of muscovite is presented. The article contains also the citation of the basic tensor literature.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('844', 75, '2013', 'Vyučovanie astronómie na 2. stupni základných škôl v Slovenskej republike', 'Teaching Astronomy at the Second Primary Education Grade of the Primary School in the Slovak Republic', '', 'Article', '1335-4981', '', '51', '58', 'Obzory matematiky, fyziky a informatiky', '', 'Astronomy does not belong among subjects that are taught at schools in Slovak republic. Astronomical curriculum is scattered in the individual, mainly natural science subjects. Astronomy is generally rated as very suitable subject for the teaching of the natural sciences. For young people it is one of the most accessible and permanently fascinating science. Beauty of space objects and the size of the universe are so inspirational and therefore astronomy stimulates a large number of young people to choose careers in science and technology. The paper deals with the possibility of integration of astronomy curriculum into education at secondary schools in the Slovak republic.', '');
