INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('849', 75, '2013', 'Využitie počítačovej simulácie didaktickej hry vo vyučovaní pravdepodobnosti', 'The Use of Computer Simulation of Didactic Games in Teaching Probability', '', 'Article', '1335-4981', '', '1', '10', 'Obzory matematiky, fyziky a informatiky', '', 'Didactic games play an important role in mathematics education. Using these games, students can acquire knowledge without being aware that they actually learn, because they are positively motivated and highly engaged in the process of game. In teaching the topic of probability we can use computer simulations to demonstrate the probabilistic phenomena. The goal of the article is to suggest a probabilistic didactic game Chuck and Luck using computer simulation, graphical and tabular view in MS Excel.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('850', 75, '2013', 'Pravdepodobnosť a lineárnosť', 'Probability and Linearity', '', 'Article', '1335-4981', '', '11', '18', 'Obzory matematiky, fyziky a informatiky', '', 'Applying elementary approach, we prove the linearity of mean value of random variables, both for discrete and continuous case.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('851', 75, '2013', 'Jeden pohl’ad na obsah matematického vzdelávania v primárnej škole na Slovensku od roku 1989 po súčasnosť', 'A Glimpse at the Content of Mathematical Education in Primary School in Slovakia from 1989 to the Present', '', 'Article', '1335-4981', '', '19', '26', 'Obzory matematiky, fyziky a informatiky', '', 'Content of mathematical education in primary school in Slovakia has been affected by the two curricular changes in recent twenty year: new curriculum for primary stage mathematics introduced in 1995 and the new law on State Programme of Education (National Curriculum) passed in 2008. Both steps meant on the one hand a certain reduction of the scope of mathematical syllabus in the first four years of elementary schooling, but, on the other hand the mathematical instruction has been enriched by some new themes.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('852', 75, '2013', 'Ako študenti stredných škôl hodnotia kvalitu vyučovania programovania', 'High School Students Evaluate the Quality of Teaching Programming', '', 'Article', '1335-4981', '', '27', '42', 'Obzory matematiky, fyziky a informatiky', '', 'Grammar schools belong to a higher level of secondary education. Their role is to prepare students for further study at any university. Computer education is implemented in a number of ways here. Programming problems can be a part of informatics classes, or they can be taught as a separate subject. The author of this paper conducted research aimed at assessing the teaching of programming as a separate subject at grammar schools in Slovakia and, for comparison, in the Czech Republic as well, since these countries and their education systems have developed in a similar
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('853', 76, '2013', 'O problematice otázek a odpovědí (první část)', 'Formal Issues in Questions and Answers  (Part One)', '', 'Article', '1335-4981', '', '1', '18', 'Obzory matematiky, fyziky a informatiky', '', 'When we study, we must ask. The article points out the possibility of partial formalization of such activities. The question starts every scientific
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('854', 76, '2013', 'Náhodné stretnutie  viacerých ľudí v čase', 'Chance  of Meetings at a given spot', '', 'Article', '1335-4981', '', '19', '34', 'Obzory matematiky, fyziky a informatiky', '', 'One of classical problems on geometrical probability is calculating
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('855', 76, '2013', 'Orbital Mechanics: Its Methods and Scope ', 'Orbital Mechanics: Its Methods and Scope', '', 'Article', '1335-4981', '', '35', '60', 'Obzory matematiky, fyziky a informatiky', '', 'The science of orbital mechanics grew out of the attempts at finding approximate solutions to the Newton’s three-body problem. Two solutions have been of partic-ular interest in the context of the interplanetary trajectory design: the Hohmann trajectories and the gravity-assist trajectories. The ideal Hohmann trajectories serve mostly as planning benchmarks; the proximate Hohmann trajectories are usually employed for flights to the targets close to Earth. Gravitational interaction between a planet and an approaching spacecraft may result in the spacecraft being catapulted into a higher orbit or being slowed down. Trajectories modified by such actions are referred to as the gravity-assist (or gravity-assisted) trajectories. Such trajectories make possible reaching the distant and/or difficult targets. The Hohmann trajectories and gravity-assist trajectories may be combined into composite trajectories. The NASA spacecraft Voyager-2 (launched in 1977) flew along a Hohmann ellipse to Jupiter, then it executed gravity-assist flybys of Jupiter (1979), Saturn (1981), Uranus (1986), and Neptune (1989). The encounter with Neptune catapulted Voyager-2 out of the Solar System. The gravity-assist flybys allow manipulation of the orbits of the captured probes. The NASA/ESA/ASI Cassini-Huygens mission provides an extreme example: each Titan flyby has been used to shape the probe’s orbits around Saturn. It is anticipated that before the end of the mission (2017), over a hundred Titan gravity-assist flybys will take place. In every system of two massive bodies there exist five points, the Lagrange or libration points, around which a constant-pattern revolution by a third body of negligible mass may be maintained with a small expenditure of fuel. These quasi-circular trajectories are known as the halo orbits. In the Sun-Earth system, the point L1 offers unobstructed observations of the Sun, while the point L2 offers a wide-sky visibility. The first spacecraft that orbited the point L1 was the NASA/ESA International Sun Explorer 3 (1978). The NASA probe Genesis visited both points, L1 and L2 (2004). The weak stability zones between the planetary bodies allow further development of the nonconventional trajectories. Gliding through the weak stability zone in the Moon-Earth system, the ESA probe SMART-1 reached the Moon after thirteen months (2004). Lagrangian trajectories connect weak stability zones of all the major bodies in the Solar System. These trajectories constitute a constantly changing grid referred to as the Planetary Transport Network. The NASA/JPL Deep Space Network (DSN) provides tracking and navigation for the flights within the Solar System. ', '');
