INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('915', 81, '2014', 'Úplná indukcia (druhá časť)', 'Total Induction (2nd part)', '', 'Article', '1335-4981', '', '1', '12', 'Obzory matematiky, fyziky a informatiky', '', 'Many assertions about natural numbers are proved by total induction. In two parts of this contribution we present both simple and hard examples of using induction. We present now the second part.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('916', 81, '2014', 'Zadania domáceho kola Olympiády v informatike', 'Tasks of the Domestic Cycle of the Olympiad in Informatics', '', 'Article', '1335-4981', '', '13', '19', 'Obzory matematiky, fyziky a informatiky', '', 'This article contains problem statements used in the Slovak Olympiad in Informatics. Problems presented in this article are used in the first round of category A in the school year 2014/15.', '');
