INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('918', 81, '2014', 'On rotations of geometrical figures', 'On rotations of geometrical figures', '', 'Article', '1335-4981', '', '21', '24', 'Obzory matematiky, fyziky a informatiky', '', 'The paper presents some original solutions to a certain problem by rolling coins (circles) derived from a book by David Wells The Penguin Book of Curious and Interesting Puzzles, and also proposes several generalizations of the problem.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('919', 81, '2014', 'Zadania úloh 64. ročníka Matematickej olympiády', 'Tasks of the First Cycle of the 64th Mathematics Olympiad', '', 'Article', '1335-4981', '', '25', '36', 'Obzory matematiky, fyziky a informatiky', '', 'In this paper, we publish the problems of the homework round of the 64th year of Mathematical Olympiad.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('920', 81, '2014', 'Výstrel do vesmíru – sci-fi alebo realita', 'Shot into Space – Sci-fi or Reality?', '', 'Article', '1335-4981', '', '37', '42', 'Obzory matematiky, fyziky a informatiky', '', 'This article investigates possibility of delivering cargo into space by shooting it with long range gun. This method was proposed by Jules Verne in his sci-fi book From the Earth to the Moon, later investigated experimentally in 60’s of 20th century. It can be shown that projectile can reach low Earth orbit if the lenght of barrel is long enough and projectile is driven by light gas. Such way of cargo delivery would be much cheaper than transporting it by shuttle or space rocket.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('921', 81, '2014', 'Vstupné vedomosti študentov bakalárskeho štúdia na FMFI UK v Bratislave v úlohe zadanej formou experimentu', '', '', 'Article', '1335-4981', '', '43', '56', 'Obzory matematiky, fyziky a informatiky', '', 'This paper deals with the research on knowledge level of students, enrolling for the university study specialized on physics. The research is based on an assignment in a form of experiment. In the period of three years 2011-2013, the research covered 208 students. In 2013 the students achieved a statistically remarkable lower
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('922', 81, '2014', 'Bezpečná a efektívna prevádzka jadrových elektrární', 'Safe and Efficient Operation of Nuclear Power Plants', '', 'Article', '1335-4981', '', '57', '60', 'Obzory matematiky, fyziky a informatiky', '', 'In Slovakia, there are two nuclear power plants (NPP) in operation; namely
