INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('925', 82, '2014', 'Rovinná Voronojova teselácia', 'Planar Voronoi Tessellation', '', 'Article', '1335-4981', '', '1', '8', 'Obzory matematiky, fyziky a informatiky', '', 'In the article the concept planar Voronoi tessellation is briefly explained and its application in different branches is showed.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('926', 82, '2014', 'Rozklady', 'Partitions', '', 'Article', '1335-4981', '', '9', '17', 'Obzory matematiky, fyziky a informatiky', '', 'The aim of this work is to introduce the reader into the problem of partitions. Gradually, on isolated examples of models of this concept, we show its importance in Mathematics. In conclusion, we formulate a sufficiently general definition of a partition, which then will no longer be only a formal knowledge of a student. The impulse to write this article were some mistakes in study materials published on the Internet by teachers of Mathematics. This article is intended for prospective teachers of Mathematics as well as their teachers.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('927', 82, '2014', 'Vizualizácia rozdielov medzi racionálnymi a iracionálnymi číslami', 'Visualization of Differences between Rational and Irrational Numbers', '', 'Article', '1335-4981', '', '17', '26', 'Obzory matematiky, fyziky a informatiky', '', 'In present time, a weak attention is devoted to real numbers teaching in grammar schools. The students have serious difficulties to determine the representatives of rational and irrational numbers, and to represent a real number on a number axis. This article demonstrates how to make an appropriate use of mathematical software for the visualization of the difference between rational and irrational numbers. We introduce a proposal of visualization of Pythagorean Theorem based on the ancient idea of commensurability. The demonstration of the diference between rational and irrational numbers is also shown on the example of \"barcode\" and \"number walk\".', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('928', 82, '2014', 'Gotické ornamenty ako motivačný prostriedok vo vyučovaní', 'Gothic Ornaments as a Motivational Tool in Teaching', '', 'Article', '1335-4981', '', '27', '36', 'Obzory matematiky, fyziky a informatiky', '', 'In the article we focus on connecting the teaching geometry with visual art. We focus on traceries of Gothic period and their geometrical constructions and principles. Constructions are simply constructed and the result is aesthetically nice construction, and we will use dynamic software GeoGebra to construct them.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('929', 82, '2014', 'Physical Processes in Nature - The Soil', 'Physical Processes in Nature - Soil', '', 'Article', '1335-4981', '', '37', '43', 'Obzory matematiky, fyziky a informatiky', '', 'This is a first of the planned articles relating to unified approach of negotiating and teaching methods in common events of the Nature. We deal with the problems of soil; physic-chemical properties, formation and evolution. We intend to show the rigorous impact of physics, chemistry, geography-geophysics, weather and other ones on the basic properties of the soil.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('930', 82, '2014', 'XIX. medzinárodná konferencia DIDFYZ´14 Vymedzenie obsahu školskej fyziky, Račkova dolina 15.-18. október 2014', 'XIXth International Conference DIDFYZ´14 The Definition of the Content of School Physics', '', 'Article', '1335-4981', '', '44', '44', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('931', 82, '2014', 'Určenie parametrov rastu znalostí opakovaným riešením fyzikálnych úloh', 'Determination of the Parameters of Knowledge Growth via Repeated Solving of Physics Tasks', '', 'Article', '1335-4981', '', '45', '49', 'Obzory matematiky, fyziky a informatiky', '', 'Knowledge growth models based on first principles play a fundamental role in cognitive sciences. Authors submit an extension of the ENKI (Efficacy Norm of Knowledge Increase) model from 2005 together with actual test results. Tests were administered by the method developed for the purpose of model ENKI, which involves problem solution with immediate feedback. ENKI was applied to the topic of parallel and serial configuration of resistors in electrical circuits, and 74 pupils of six elementary schools took the test. We found that 37% of pupils have mastered the subject, 13% of pupils showed no improvement, while 50% of pupils showed increased proficiency in accordance with the ENKI model (at significance level Alpha=0,05). After attempting solution of six typical problems with immediate feedback, 90% of pupils achieved mastery of the given subject.', '');
