INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('940', 83, '2015', 'Medzinárodný rok svetla (2015) vo vyučovaní fyziky', '', '', 'Article', '1335-4981', '', '39', '55', 'Obzory matematiky, fyziky a informatiky', '', 'The 68th session of the UN General Assembly on 20 December 2013 adopted a resolution which declared the year 2015 as the International Year of Light and Light-based Technologies. The UN team thus expressed their recognition of scientific findings in the field of optical phenomena and highlighted the importance of research on optical technologies which has recently contributed significantly to meet the challenges in energetics, health care, industry, environment, agriculture, as well as in science per se. Light plays a crucial role in everyday life and therefore its research is a cross-discipline endeavor of science and technology of the 21st century. This is also confirmed by the fact that the 2014 Nobel Prize in Physics was awarded for the discovery of effective blue light source based on GaN crystals. Given the global recognition of the significance of the light phenomena for mankind, many events, including professional and educational activities are being organized all over the world in order to popularize and disseminate the research results in the field. The light phenomena are also included in the content of general education and the major themes of the IYL are studied on all levels, from primary schools to universities. The authors of the present article discuss the light phenomena and propose a few suggestions regarding the themes which can be used at primary and secondary levels of education. The themes primarily focus on light-emitting diodes (LED: Light Emitting Diode).', '');
