INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('942', 83, '2015', 'Akí študenti sú prijatí na vojenskú akadémiu z hľadiska ich pripravenosti z fyziky', '', '', 'Article', '1335-4981', '', '57', '62', 'Obzory matematiky, fyziky a informatiky', '', 'In the academic year 2014/2015, 37 students of the full-time Bachelor study at the Armed Forces Academy of Gen. M. R. Štefánik in Liptovský Mikuláš began to attend the courses in the scientific fields: Electronic systems, Computing systems, networks and services and Weapon systems, weapons and their parts. This paper presents the results from the questionnaire of which the teachers of physics working at the Armed Forces Academy learned what kind of students are admitted to the military academy in terms of their Physics readiness. The obtained data are necessary for lecturers’ subsequent educational work with students.', '');
