INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('973', 86, '2015', 'Stereológia (takmer) pre laikov', '', '', 'Article', '1335-4981', '', '7', '14', 'Obzory matematiky, fyziky a informatiky', '', 'In the lively and inanimate nature the features of three-dimensional objects are often derived from their cuts and projections in subspace of lower dimension. For this is used not very well-known interdisciplinary science–stereology. The paper deals with its brief characteristics, basic stereological
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('974', 86, '2015', 'Osobní pohled na monografii Komparativní analýza primárního matematického vzdělávání', '', '', 'Article', '1335-4981', '', '15', '19', 'Obzory matematiky, fyziky a informatiky', '', 'Text presents review of the publication Comparative Analysis of Primary Mathematics Education in Slovakia and Abroad. It is one of the outputs of several years of research done by the members of the Department of Mathematic Education at the Faculty of Education, University of Presov. It introduces valuable summary of many elements of the curriculum of selected countries prepared for TIMSS research in a group of 10-year-old pupils.', '');
