INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('977', 86, '2015', 'Gravitácia a rast rastlín', '', '', 'Article', '1335-4981', '', '39', '48', 'Obzory matematiky, fyziky a informatiky', '', 'One of the possibilities how to develop students{^I}„ science process skills is solving simple research tasks in which students{^I}„ procedures are similar to real scientific methods. This article brings up an interesting research task designed mainly for students of higher level of secondary education. The task has interdisciplinary character and its solution requires common tools.', '');
