INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('985', 87, '2016', 'Interpretácia jednej difúznej slovnej úlohy', '', '', 'Article', '1335-4981', '', '1', '8', 'Obzory matematiky, fyziky a informatiky', '', 'In our everyday lives we are commonly exposed to situations that require using logic and creative thinking. Their developing is natural to mathematical education and is often reflected into questions in the field of recreational mathematics. This paper is devoted to a logic question whose solution is largely dependent on the ability of a solver to interpret information from the assignment. Situations, where interpretation is ambiguous, force the solvers to think deeper; when these are accompanied by discussions, they are usually very productive and can even bring a whole new perspective to the question.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('986', 87, '2016', 'Comparing mathematical competences to school achievement in school tests', NULL, '', 'Article', '1335-4981', '', '9', '24', 'Obzory matematiky, fyziky a informatiky', '', 'The evaluation of school tests used to be analytical in mathematics education, giving partial points to every thinking units, according to the evaluation system of the maturation test in Hungary. So it mainly measures the level of the acquirements of the curriculum. How can we take into account the development of the students’ mathematical competences together with this material-based evaluation? In my research I’ve examined 4 school tests of two classes (grade 11 and 12) of a secondary school according to a competence evaluation system and compared it to the traditional evaluation. Doing this, I try to find out the connection between the students’ school achievement (which we used to evaluate with marks from 1 to 5) and their mathematical competences. What can be the reason behind a weak school achievement? From the result of such a comparison we can define the ways of further development: what should the teacher concentrate on, the content, the sensible learning or the development of skills and abilities.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('987', 87, '2016', 'Tvorba limít', '', '', 'Article', '1335-4981', '', '25', '31', 'Obzory matematiky, fyziky a informatiky', '', 'As we know, there are very little exercises of the limit of type 00 in literature having the result different from 1. We found only one such example in the listed references. From this reason we created a collection of such limits. We must note that much more important is the method of the creation of (not only) such exercises.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('988', 87, '2016', 'Tímová súťaž  MATEMATICKÝ B-DEŇ pre 3-4 členné tímy stredoškolákov', '', '', 'Article', '1335-4981', '', '32', '34', 'Obzory matematiky, fyziky a informatiky', '', 'In this contribution we briefly describe the international team competition Mathematical B-day in which the Slovak students have taken part already for five years.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('989', 87, '2016', 'The Role of Dimensional Analysis in Teaching Physics  ', NULL, '', 'Article', '1335-4981', '', '35', '44', 'Obzory matematiky, fyziky a informatiky', '', 'Dimensional analysis is a simple qualitative method for determining essential connections between physical quantities. It is applicable to a multitude of physics problems, many of which can be introduced early on in a university physics curriculum. Despite the relative simplicity of the approach, it is rarely included in physics curricula. Here, we apply dimensional analysis to find the radiated power from an electric dipole. Employing dimensional analysis, we demonstrate a straightforward way to derive the latter without the need for complex mathematical treatments.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('990', 87, '2016', 'Bude mať kto kvalifikovane učiť fyziku?', '', '', 'Article', '1335-4981', '', '45', '56', 'Obzory matematiky, fyziky a informatiky', '', 'We present outputs from the research on the age structure and qualification structure of physics teachers at lower secondary and upper secondary schools in Slovakia. Presented outputs display the state in June 2012. An electronic survey was sent to all schools elementary and secondary schools in Slovak republic. Totally 618 teachers from 395 schools were involved in the research. Information about their age, praxis in teaching physics, qualification, taught subjects and preferred areas of lifelong education were collected in the frame of presented research.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('991', 87, '2016', 'EUROPEAN UNION SCIENCE OLYMPIAD 2016 (14. ročník) Správa o účasti reprezentácie Slovenskej republiky', '', '', 'Article', '1335-4981', '', '57', '62', 'Obzory matematiky, fyziky a informatiky', '', '', '');
