INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('993', 87, '2016', 'Významného životného jubilea sa dožil profesor Pavol Kluvánek vedúca osobnosť Žilinskej školy v matematickej teórii dopravy', '', '', 'Article', '1335-4981', '', '67', '68', 'Obzory matematiky, fyziky a informatiky', '', '', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('994', 88, '2016', 'Tři důkazy Morleyovy věty', '', '', 'Article', '1335-4981', '', '1', '12', 'Obzory matematiky, fyziky a informatiky', '', 'Three elegant and relatively new proofs of Morley’s theorem, one of the most attractive results in plane geometry, are presented.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('995', 88, '2016', 'Galileov pohľad  na nekonečno', '', '', 'Article', '1335-4981', '', '13', '24', 'Obzory matematiky, fyziky a informatiky', '', 'Theory of sets, founded by George Cantor (1845–1918), systematically deals with the notion of infinity. Observe that mathematical studies of infinity and related paradoxes by Bernard Bolzano (1781–1848) are of an earlier vintage. But the trailblazer in this area is Galileo Galilei (1564–1642), the founder of modern natural science. The goal of our article is to brush up Galileo’s revolutionary and modern ideas on infinity. In his treatise Discorsi e dimostrazioni matematiche intorno a due nuove scienze, published in 1638, Galileo discussed ways how to compare the size of infinite sets, the bijection between points of intervals with different lengths, and the equality of areas of an interval and a single point. He studied other paradoxes of infinity pointing against the Aristotle’s maxim the whole is greater than the part. Galileo’s ideas can serve as an interesting complement to high school mathematics.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('996', 88, '2016', 'Inovácie profesijnej prípravy v oblasti informatiky u študentov študijných programov ekonomického a manažérskeho zamerania', '', '', 'Article', '1335-4981', '', '25', '36', 'Obzory matematiky, fyziky a informatiky', '', 'The author present in this paper some results of a research with a broader concept, of which one of the goals was to map the current state of informatics education in the scope of selected economic and management study profiling (ISCED 5), and thus contributing to solving the issue of modernization and optimization of teaching in the field of informatics and to focus the content of the curriculum on the requirements determined by practice and labor market for knowledge and skills in the study area. In the paper the authors present a statistical analysis and interpretation of the results of processing the student responses to selected items within the surveyed area entitled \"What I would like to learn\" through items, which participants were asked to what extent they believe is the relevant learning subject content interesting and significant for the education in the context of their study profiling, or significant for their professional future.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('997', 88, '2016', 'Loedelove diagramy a riešenie paradoxov', '', '', 'Article', '1335-4981', '', '37', '42', 'Obzory matematiky, fyziky a informatiky', '', 'We solve three paradoxes in special theory of relativity by using Loedel’s diagrams.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('998', 88, '2016', 'The Physical Processes  in Nature – The Water', '', '', 'Article', '1335-4981', '', '43', '49', 'Obzory matematiky, fyziky a informatiky', '', 'This paper is the second part of our series demoted the description of the physical processes in nature. The first was the “soil” published in 2014 [1]. Represent our aim is to introduce the integrated approach into science education, to give a practical and concrete help for teacher in their teaching activity. In this series we collect the phenomena, events which can the connection among physical, biological, chemical and geological concepts leading to integrated approach to fundamental viewpoints. In this second part we deal with physic-chemical properties of water through natural examples: what role plays the water in processes and how the water’s properties are determining the changes in different water related performances.', '');
