INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('1017', 90, '2016', 'Vyhl’adávanie prvočinitel’ov v obore celých komplexných čísel', '', '', 'Article', '1335-4981', '', '21', '29', 'Obzory matematiky, fyziky a informatiky', '', 'The main part of the paper deals with a method, similar to the sieve
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('1018', 90, '2016', 'Rozvíjanie spôsobilosti plánovať experiment na vyučovaní fyziky na ZŠ', '', '', 'Article', '1335-4981', '', '31', '40', 'Obzory matematiky, fyziky a informatiky', '', 'Science process skills have a key position in today\'s science education - in the education standard, there is the process standard forward to the content standard. However, this change in goals requires a new assessment strategy, as it is about process knowledge. It is necessary to define the characteristics of each skill and suggest indicators for their assessment. We present method of formative assessment and verification of this method in education process.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('1019', 90, '2016', 'Konferencie DIDFYZ ako historická súčasť didaktiky fyziky a vyučovania fyziky v Česko-Slovensku', '', '', 'Article', '1335-4981', '', '41', '58', 'Obzory matematiky, fyziky a informatiky', '', 'Conferences DIDFYZ (Didactics of Physics) which have been organized since 1977 every two years in the High Tatras in Slovakia have focused on basic issues of the Theory of teaching Physics. During forty years of their existence, conferences have become a useful forum for the teachers and researchers from the Czech Republic, Slovakia and other countries, and dealt with professional as well as practical questions of teaching physics at primary and secondary schools. The article analyses how the DIDFYZ conferences have shaped and contributed to the field of science and scientific schools in the Czech Republic, Slovakia and abroad.', '');
