INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('1037', 93, '2017', 'Vytváranie predstáv  o toku energie v biosfére', '', '', 'Article', '1335-4981', '', '35', '46', 'Obzory matematiky, fyziky a informatiky', '', 'The science education key goal is comprehension of phenomena and processes in nature. In this article, we present a series of activities focused on comprehension of energy flow in the biosphere. As a part of the last grade elementary education, these activities offer an opportunity to strengthen knowledge on essential elements of science teaching content such as conversion of light into heat, sunlight spectrum, light transmission and absorption, spectral analysis, photosynthesis, conversion of thermal energy into chemical and reverse, method of food energy value assessment.', '');
