INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('1059', 95, '2017', 'Benchmarking v záverečných testoch z úvodných kurzov programovania', '', '', 'Article', '1335-4981', '', '1', '12', 'Obzory matematiky, fyziky a informatiky', '', 'We inform about an international initiative of computer science teachers who have decided to do benchmarking in final tests of their introductory programming courses at their schools. This benchmarking is based on a set of 10 specified programming questions in modifications for programming languages Python, Java or C — according to a programming language taught in their own institution. We started to cooperate with authors of these questions at two Slovak universities in 2016/17 academic year. We have prepared a version for C programming language with instructions in Slovak language. We present these programming tasks in this article so they could be used by teachers in first programming courses at universities and at secondary vocational schools as well.', '');
