INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('1126', 103, '2019', 'Quo vadis, slovenská matematika?', '', '', 'Article', '1335-4981', '', '1', '7', 'Obzory matematiky, fyziky a informatiky', '', 'On the basis of the leaving school report from the real high school of author\'s father since 1919 in Russia, where there are four marks on mathematics as well as one on mathematical geography, the author describes the development of the real high school system in Germany, Austria, Russia, Poland, Hungary, Czechoslovakia and in nowadays Slovakia. It is a sad fact whilst 100 —200 years ago, intellectuals knew very well that the progress in industry, technology, economy is not possible without mathematics, nowadays in Slovakia after 100 years we only to start to discuss what to do with abandoned mathematical education. 
