INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('1141', 105, '2019', 'Výzkumný přístup ve školské matematice', '', '', 'Article', '1335-4981', '', '1', '14', 'Obzory matematiky, fyziky a informatiky', '', 'Investigation is a method by which a teacher can teach mathematics at almost any level and also a method by which students can learn by doing mathematics. The typical approach to research at school is as follows: mathematical situation (a problem is presented), experimentation, conjecture, conjecture verification and proof which produces the final result: a theorem (answer). This method makes it possible for students to develop mathematics, rather than merely learning the work of others. The investigative method melds easily with other strategies. 
