INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('1272', 117, '2022', 'Rovesnícke hodnotenie ako nástroj učenia sa', '', '', 'Article', '1335-4981', '', '1', '13', 'Obzory matematiky, fyziky a informatiky', '', 'This article deals with the peers\' assessment and its possible impact on the students\' topic understanding. It contents results of the research taking place in mathematics classes within two 2 different school years and levels by teaching topics of the ratio, direct and indirect proportionality, and theory of numbers. Our results show that there should be some positive connection between the usage of the peers\' assessment within the educational process and the pupils\' topic understanding. At the same time, this article also presents the Peer-Assessment rubrics and the students\' feedback on the usage of such rubrics.', '');
INSERT INTO publications (`id`, `issue_id`, `actualyear`, `title`, `title_eng`, `bibtex_id`, `type`, `issn`, `isbn`, `firstpage`, `lastpage`, `journal`, `keywords`, `abstract`, `doi`) VALUES ('1273', 118, '2022', 'Opustil nás prof. RNDr. Tibor Katriňák, DrSc.', '', '', 'Article', '1335-4981', '', '1', '16', 'Obzory matematiky, fyziky a informatiky', '', 'Profesor Tibor Katrihak passed away on May 23, 2022 at the age 85. This article aims at looking back at the scientific and human legacy that Tibor left in the Slovak and international communities of algebraists as well as in the communities of university teachers, researchers and students at Faculty of Mathematics, Physics and Informatics of Comenius University in Bratislava, where he spent most of his professional life. He became a world-recognized authority in the scientific fields of Lattice Theory and Universal Algebra and a leading specialist in the areas of pseudocomplemented lattices and semilattices. He scientifically brought up and guided eight doctoral students. Tibor will be missed as one of the most emblematic figures of Slovak mathematics. 
